/**
 * "This server is ready" — the one place that finishes a server's setup state
 * when it becomes RUNNING through any path OTHER than a clean provision().
 *
 * Bug (signup-friction report 2026-10-06): two Oct 2 game servers (Valheim
 * 8 GB, Project Zomboid 8 GB) failed PROVISION 3/3 at the game-port check,
 * were brought back (status flipped to RUNNING outside provision(), then a
 * GAME_REINSTALL confirmed the game port), and stayed RUNNING for days with
 * `provisioningStep = "Installing the game — this one is a large download…"`,
 * the old `provisionError`, and no `server_deployed` email. Only provision()'s
 * own success branch ever cleared the step or sent the ready email; every
 * other way into RUNNING (power START on an ERROR row, admin reconcile, game
 * reinstall, restore, unsuspend, the sandbox provision branch) left them.
 *
 * `markServerReady` is called from each of those paths. It:
 *   - clears `provisioningStep` (and `provisionError` when the server never
 *     completed setup), so neither admin views nor the customer see stale text;
 *   - sends the deduped `server_deployed` email ONLY when the server never got
 *     one and had never finished setup (a stale step or a provision error on
 *     the row) and is recent (`READY_EMAIL_MAX_AGE_DAYS`) — an old server that
 *     is simply restarted is never emailed.
 *
 * Plain module (no server-only, no next/headers) — the worker imports it.
 */
import { db } from "./db";

export const READY_EMAIL_MAX_AGE_DAYS = 30;

export type ReadyDecision = { clearStep: boolean; clearProvisionError: boolean; sendReadyEmail: boolean };

/** Pure decision (unit-tested). `confirmed` = the caller verified the service/port is really up. */
export function readyDecision(s: {
  status: string;
  provisioningStep: string | null;
  provisionError: string | null;
  createdAt: Date;
  setupQueuedAt?: Date | null;
}, opts: { confirmed: boolean; now?: Date }): ReadyDecision {
  const now = opts.now ?? new Date();
  const neverFinished = !!(s.provisioningStep && s.provisioningStep.trim()) || !!s.provisionError;
  const recent = now.getTime() - s.createdAt.getTime() < READY_EMAIL_MAX_AGE_DAYS * 24 * 60 * 60 * 1000;
  if (s.status !== "RUNNING" || s.setupQueuedAt) return { clearStep: false, clearProvisionError: false, sendReadyEmail: false };
  return {
    clearStep: !!s.provisioningStep,
    clearProvisionError: neverFinished && opts.confirmed && !!s.provisionError,
    sendReadyEmail: neverFinished && opts.confirmed && recent,
  };
}

/**
 * Finish a server's setup state after it reached RUNNING outside provision().
 * `confirmed`: true only when the caller just proved the server is really
 * usable (game port answered, VM status read as running). Never throws.
 */
export async function markServerReady(serverId: string, opts: { confirmed: boolean; source: string }): Promise<ReadyDecision | null> {
  try {
    const s = await db.server.findUnique({
      where: { id: serverId },
      select: { id: true, status: true, provisioningStep: true, provisionError: true, createdAt: true, setupQueuedAt: true, userId: true, user: { select: { email: true } } },
    });
    if (!s) return null;
    const d = readyDecision(s, { confirmed: opts.confirmed });
    if (d.clearStep || d.clearProvisionError) {
      await db.server.update({
        where: { id: s.id },
        data: { ...(d.clearStep ? { provisioningStep: null } : {}), ...(d.clearProvisionError ? { provisionError: null } : {}) },
      });
    }
    if (d.sendReadyEmail) {
      // Deduped per server inside sendServerDeployedEmail (EmailLog), so a
      // customer who already got it is never emailed twice.
      const { sendServerDeployedEmail } = await import("./server-deployed-email");
      const full = await db.server.findUnique({ where: { id: s.id }, include: { node: true, dedicatedIp: true, portForwards: true, plan: true, osTemplate: true } });
      if (full) await sendServerDeployedEmail(full as never, s.user);
      console.log(`[server-ready] ${serverId} finished setup via ${opts.source}; ready email handed to the deduped sender`);
    }
    return d;
  } catch (e) {
    console.error("[server-ready] failed", serverId, e instanceof Error ? e.message : e);
    return null;
  }
}

/** Minutes a RUNNING server may keep a provisioningStep before the watchdog clears it. */
export const STALE_STEP_MINUTES = 30;

/**
 * Watchdog (worker sweep): RUNNING servers whose provisioningStep is older
 * than STALE_STEP_MINUTES and that have no in-flight job. Clears the step;
 * does NOT send the ready email (the watchdog has not verified the game is
 * up) — it raises one admin notification listing them so staff can check.
 * Returns the ids it cleared.
 */
export async function staleProvisioningStepSweep(now = new Date()): Promise<string[]> {
  const cutoff = new Date(now.getTime() - STALE_STEP_MINUTES * 60_000);
  const rows = await db.server.findMany({
    where: { status: "RUNNING", provisioningStep: { not: null }, updatedAt: { lt: cutoff }, setupQueuedAt: null },
    select: { id: true, hostname: true, jobs: { where: { status: { in: ["QUEUED", "RUNNING"] } }, select: { id: true }, take: 1 } },
    take: 50,
  });
  const idle = rows.filter((r) => r.jobs.length === 0);
  if (!idle.length) return [];
  await db.server.updateMany({ where: { id: { in: idle.map((r) => r.id) } }, data: { provisioningStep: null } });
  try {
    const admins = await db.user.findMany({ where: { role: "ADMIN" }, select: { id: true } });
    const title = `Setup text cleared on ${idle.length} running server(s)`;
    const body = `These servers were RUNNING but still showed a setup step and may never have had their ready email: ${idle
      .map((r) => r.hostname)
      .join(", ")}. Check each one, then use Reconcile or send the ready email if appropriate.`;
    if (admins.length) {
      await db.notification.createMany({ data: admins.map((a) => ({ userId: a.id, title, body, href: "/admin/servers" })) });
    }
  } catch {
    /* alerting is best-effort */
  }
  return idle.map((r) => r.id);
}

