/**
 * "Queued for setup" — the capacity safety valve (owner, 2026-10-06):
 *
 *   "I don't want to flat-out tell people they are unavailable ... We need to
 *    portray ourselves as a large hosting provider with no limits."
 *
 * So an order is ALWAYS accepted in the region the customer chose. When no node
 * there has room at that moment (fleet RAM ceiling, every node in the region
 * refused by the scheduler — which includes the live RAM guard when
 * NXEON_RAM_GUARD=enforce — or the disk pool), the server is created and
 * charged exactly as normal but WITHOUT a PROVISION job and without a node:
 *
 *   Server.setupQueuedAt / setupQueueRegion / setupQueueReason are set,
 *   provisioningStep carries the positive customer copy (queuedStepText),
 *   staff get an URGENT alert naming region / size / customer (alertSetupQueued),
 *   and worker/signup-sweeps.ts `setupQueueSweep` re-checks placement every few
 *   minutes, then assigns the node, extends expiresAt by the time spent
 *   waiting (the customer never pays for queue time) and enqueues PROVISION.
 *   The normal provision success path sends the existing "server is ready" email.
 *
 * A node is never overfilled to avoid the queue: placement still goes through
 * the same scheduler and guards; the queue is what happens INSTEAD of a refusal.
 *
 * Plain module (no server-only / next/headers): the worker imports it.
 */
import { db } from "./db";
import { getSettingInt } from "./settings";
import { logError } from "./log";
import { recordActivity } from "./activity-events";

export type SetupQueueReason = "fleet_ram" | "region_full" | "disk";

/** Customer copy. Never "unavailable", "sold out", "limited" or "capacity". */
export function queuedStepText(expectedHours: number): string {
  const h = Number.isFinite(expectedHours) && expectedHours > 0 ? Math.round(expectedHours) : 24;
  return `Your server is being prepared. We'll email you the moment it's ready, usually within ${h} hour${h === 1 ? "" : "s"}.`;
}

export async function setupQueueExpectedHours(): Promise<number> {
  const h = await getSettingInt("setup_queue_expected_hours", 24);
  return h > 0 && h <= 24 * 14 ? h : 24;
}

/** The fields a queued server is created with (spread into server.create data). */
export async function queuedServerFields(region: string, reason: SetupQueueReason, now = new Date()) {
  return {
    setupQueuedAt: now,
    setupQueueRegion: region,
    setupQueueReason: reason,
    provisioningStep: queuedStepText(await setupQueueExpectedHours()),
  };
}

const REASON_TEXT: Record<SetupQueueReason, string> = {
  fleet_ram: "no node has RAM headroom under the oversell ceiling",
  region_full: "no node in the region could take it (scheduler / RAM guard)",
  disk: "the node's storage pool is too full",
};

/**
 * URGENT staff alert for a freshly queued order: in-app notification to every
 * ADMIN (shown in the admin tray) + ErrorLog at level error (which also posts to
 * NXEON_ERROR_WEBHOOK when configured). Never emails anyone. Never throws.
 */
export async function alertSetupQueued(a: {
  serverId: string;
  hostname: string;
  userId: string;
  userEmail?: string | null;
  region: string;
  ramMB: number;
  cpuCores?: number | null;
  diskGB?: number | null;
  product: "vps" | "game";
  reason: SetupQueueReason;
}): Promise<void> {
  const size = `${Math.round(a.ramMB / 1024)} GB RAM${a.cpuCores ? ` / ${a.cpuCores} vCPU` : ""}${a.diskGB ? ` / ${a.diskGB} GB disk` : ""}`;
  const who = a.userEmail || a.userId;
  const title = `URGENT: add capacity in ${a.region} — paid ${a.product === "game" ? "game server" : "VPS"} (${size}) is waiting`;
  const body = `${a.hostname} for ${who} was accepted and charged but is queued for setup: ${REASON_TEXT[a.reason]}. ` +
    `It deploys automatically as soon as a node in ${a.region} has room (enable a node, free RAM, or add one). The customer was told it's being prepared.`;
  try {
    const admins = await db.user.findMany({ where: { role: "ADMIN" }, select: { id: true } });
    if (admins.length) {
      await db.notification.createMany({ data: admins.map((u) => ({ userId: u.id, title, body, href: `/admin/servers/${a.serverId}` })) });
    }
  } catch (e) {
    console.error("[setup-queue] admin notification failed", e);
  }
  await logError("setup-queue", new Error(`URGENT capacity: ${a.product} ${size} queued in ${a.region}`), {
    userId: a.userId,
    serverId: a.serverId,
    region: a.region,
    reason: a.reason,
    ramMB: a.ramMB,
  }).catch(() => undefined);
  await recordActivity({
    type: "wizard.queued",
    userId: a.userId,
    serverId: a.serverId,
    label: `Order accepted and queued for setup in ${a.region} (${size})`,
    data: { region: a.region, reason: a.reason, ramMB: a.ramMB, product: a.product },
  });
}

/** Pure: how far to push expiresAt when a queued server is finally placed. */
export function extendedExpiry(expiresAt: Date | null, queuedAt: Date, now: Date): Date | null {
  if (!expiresAt) return null;
  const waited = Math.max(0, now.getTime() - queuedAt.getTime());
  return new Date(expiresAt.getTime() + waited);
}

/**
 * Hand a queued server to provisioning on `nodeId`: assign node, clear queue
 * state, extend expiry by the wait, enqueue PROVISION. Guarded so two sweeps
 * can never double-release (conditional update on setupQueuedAt).
 */
export async function releaseQueuedServer(serverId: string, nodeId: string, now = new Date()): Promise<boolean> {
  return db.$transaction(async (tx) => {
    const s = await tx.server.findUnique({ where: { id: serverId }, select: { setupQueuedAt: true, expiresAt: true, status: true } });
    if (!s?.setupQueuedAt || s.status !== "PENDING") return false;
    const claimed = await tx.server.updateMany({
      where: { id: serverId, setupQueuedAt: s.setupQueuedAt },
      data: {
        nodeId,
        setupQueuedAt: null,
        setupQueueReason: null,
        provisioningStep: null,
        expiresAt: extendedExpiry(s.expiresAt, s.setupQueuedAt, now),
      },
    });
    if (claimed.count !== 1) return false;
    await tx.job.create({ data: { type: "PROVISION", serverId } });
    return true;
  });
}

