  familyName?: string;
  open: boolean;
  onClick: () => void;
}) {
  return (
    <button type="button" onClick={onClick} aria-expanded={open}
            className={"flex w-full flex-col gap-3 rounded-[10px] border p-4 text-left transition-colors sm:flex-row sm:items-center " +
                       (open
                         ? "border-[rgba(59,107,232,0.5)] bg-[rgba(59,107,232,0.1)]"
                         : "border-rim-soft bg-well hover:border-[rgba(59,107,232,0.35)] hover:bg-[rgba(59,107,232,0.05)]")}>
      <Plate name="serverstack" size={24} />
      <span className="flex min-w-0 flex-1 flex-col gap-0.5">
        <span className="text-[13.5px] font-bold text-white">
          Running a community, enterprise, or commercial {familyName ?? "game"} server?
        </span>
        <span className="text-[11.8px] leading-[1.45] text-tx-faint">
          Go bigger than these four tiers — dial in the exact vCPU, RAM &amp; disk for a large
          community, a paid server network, or a business deployment, or hand it to sales and
          we&apos;ll size it with you.
        </span>
      </span>
      <span className={"btn-ghost h-[38px] flex-none px-4 text-center text-[12.5px] leading-[38px] " +
                       (open ? "border-transparent bg-[linear-gradient(100deg,#1a55cf,#6f2ee0)] text-white" : "")}>
        {open ? "Close builder" : "Build a custom server"} <span className="arw" aria-hidden>→</span>
      </span>
    </button>
  );
}

/* ── one resource slider row ─────────────────────────────────────────────── */
function ResourceSlider({ icon, label, value, unit, min, max, step, extra, rateCents, rateUnit, onChange }: {
  icon: string; label: string; value: number; unit: string;
  min: number; max: number; step: number;
  /** Units above the floor — what is actually being paid for. */
  extra: number; rateCents: number; rateUnit: string;
  onChange: (n: number) => void;
}) {
  const money = useMoney();
  const pct = max > min ? ((value - min) / (max - min)) * 100 : 0;
  const atMax = value >= max;
  return (
    <div className="flex flex-col gap-2">
      <div className="flex items-center gap-2.5">
        <Plate name={icon} size={18} />
        <span className="flex min-w-0 flex-1 flex-col leading-[1.3]">
          <span className="text-[12.5px] font-bold text-white">{label}</span>
          <span className="text-[10.8px] text-tx-faint">
            {money(rateCents)}/{rateUnit} per month above the base
          </span>
        </span>
        <span className="flex flex-none flex-col items-end leading-[1.3]">
          <span className="text-[14px] font-extrabold text-white tabular-nums">{value} {unit}</span>
          <span className={"text-[10.8px] tabular-nums " + (atMax ? "text-amber" : "text-tx-faint")}>
            {atMax ? "Self-serve max" : extra > 0 ? `+${money(extra * rateCents)}/mo` : "Included"}
          </span>
        </span>
      </div>
      <input type="range" aria-label={`${label} (${unit})`}
             min={min} max={max} step={step} value={value}
             onChange={(e) => onChange(+e.target.value)}
             className="range w-full"
             style={{ "--pct": `${pct}%` } as React.CSSProperties} />
    </div>
  );
}

/* ── the builder panel ───────────────────────────────────────────────────── */
type QuoteState =
  | { key: string; status: "checking" }
  | {
      key: string; status: "ok"; priceCents: number; termMonthlyCents: Record<number, number>;
      /** The first-term price the row will be created with, and the first
       *  term's per-term effective monthly, both from the server. */
      introPriceCents: number | null; introTermMonthlyCents: Record<number, number> | null;
      capacityOk: boolean; capacityReason?: string;
    }
  | { key: string; status: "bad"; reason: string };

  | { key: string; status: "bad"; reason: string };

export function CustomServerBuilder({ cfg, kind, family, familyName, checkoutFields, terms, onBuilt, onClose }: {
  cfg: CustomPlanConfig | GameCustomPlanConfig;
  kind: "vps" | "game";
  /** Game orders only. */
  family?: string;
  familyName?: string;
  checkoutFields?: ConfigField[];
  terms: TermOption[];
  /** Called after the custom row exists and has been selected. */
  onBuilt: () => void;
  onClose: () => void;
}) {
  const { o, cat, applyCustomPlan, applyCustomTier } = useOrder();
  const money = useMoney();
  const { floor, ceiling, rates } = cfg;
  const isGame = kind === "game" && !!family;

  // Start from the build already made this session, if there is one, so
  // "Edit custom build" reopens on what the customer chose — not a reset.
  const existing: (PlanOption | GameTier) | null = isGame
    ? cat.games.find((g) => g.family === family)?.tiers.find((t) => t.custom) ?? null
    : cat.plans.find((p) => p.custom) ?? null;

  const engineMax = isGame ? engineMaxPlayers(checkoutFields) : null;
  const sliderMax = isGame
    ? Math.max(2, Math.min(playerSliderMax(family as GameFamily), engineMax ?? Infinity))
    : 0;

  /* Round a recommendation onto the sliders' own grid (whole GB of RAM, 10 GB
     of disk above the floor) and clamp into floor..ceiling. If that lands on
     the floor exactly — i.e. the headcount fits a standard plan — nudge RAM up
     1 GB so the spec is a real custom build (a floor-identical spec is just
     "Max" and the server rightly refuses it). */
  const fromPlayers = (players: number): { spec: CustomPlanSpec; overCeiling: boolean; fitsStandard: boolean } => {
    const rec = recommendedSpecForPlayers(family as GameFamily, players);
    const raw: CustomPlanSpec = {
      cpuCores: rec.cpuCores,
      ramMB: Math.ceil(rec.ramMB / 1024) * 1024,
      diskGB: floor.diskGB + Math.ceil(Math.max(0, rec.diskGB - floor.diskGB) / DISK_STEP_GB) * DISK_STEP_GB,
    };
    const overCeiling = raw.cpuCores > ceiling.maxCpuCores || raw.ramMB > ceiling.maxRamMB || raw.diskGB > ceiling.maxDiskGB;
    const fitsStandard = raw.cpuCores <= floor.cpuCores && raw.ramMB <= floor.ramMB && raw.diskGB <= floor.diskGB;
    let spec = clampCustomPlanSpec(raw, floor, ceiling);
    if (spec.cpuCores === floor.cpuCores && spec.ramMB === floor.ramMB && spec.diskGB === floor.diskGB) {
      spec = clampCustomPlanSpec({ ...spec, ramMB: spec.ramMB + 1024 }, floor, ceiling);
    }
    return { spec, overCeiling, fitsStandard };
  };

  const initialPlayers = isGame
    ? (existing && "slots" in existing && existing.slots ? Math.min(existing.slots, sliderMax) : Math.max(1, Math.round(sliderMax / 2)))
    : 0;
  const [players, setPlayers] = useState<number>(initialPlayers);
  const [spec, setSpec] = useState<CustomPlanSpec>(() => {
    if (existing) return { cpuCores: existing.cpuCores, ramMB: existing.ramMB, diskGB: existing.diskGB };
    if (isGame) return fromPlayers(initialPlayers).spec;
    // VPS: open one clear step up from the top plan (double it), not on the
    // floor itself — the floor alone is just "Max" and can't be ordered here.
    return clampCustomPlanSpec(
      { cpuCores: floor.cpuCores * 2, ramMB: floor.ramMB * 2, diskGB: floor.diskGB * 2 }, floor, ceiling);
  });
  const playerInfo = isGame ? fromPlayers(players) : null;

  const setPlayersAndSpec = (n: number) => {
    setPlayers(n);
    setSpec(fromPlayers(n).spec);
  };
  const setDim = (k: keyof CustomPlanSpec, v: number) =>
    setSpec((s) => clampCustomPlanSpec({ ...s, [k]: v }, floor, ceiling));

  const specKey = `${spec.cpuCores}/${spec.ramMB}/${spec.diskGB}`;
  const valid = validateCustomPlanSpec(spec, floor, ceiling);
  const preview = previewPriceCents(spec, cfg);

  /* The authoritative check, debounced behind the slider. Keyed by spec so a
     slow reply for a spec the customer has already moved past is ignored.
     Game orders go through quoteCustomGamePlanAction (this family's own rate) —
     see previewPriceCents/GameCustomPlanConfig's doc for why the VPS-only
     quoteCustomPlanAction below would silently reprice a game order wrong. */
  const [quote, setQuote] = useState<QuoteState | null>(null);
  useEffect(() => {
    if (!valid.ok) { setQuote(null); return; }
    let cancelled = false;
    const key = specKey;
    setQuote({ key, status: "checking" });
    const t = setTimeout(async () => {
      try {
        const res = isGame
          ? await quoteCustomGamePlanAction({ ...spec, gameFamily: family! })
          : await quoteCustomPlanAction(spec);
        if (cancelled) return;
        if (!res.ok || res.priceCents == null) setQuote({ key, status: "bad", reason: res.error ?? "That configuration isn't available." });
        else setQuote({
          key, status: "ok", priceCents: res.priceCents,
          termMonthlyCents: res.termMonthlyCents ?? {},
          introPriceCents: res.introPriceCents ?? null,
          introTermMonthlyCents: res.introTermMonthlyCents ?? null,
          capacityOk: !!res.capacityOk, capacityReason: res.capacityReason,
        });
      } catch {
        if (!cancelled) setQuote({ key, status: "bad", reason: "Couldn't check that right now — try again in a moment." });
      }
    }, 450);
    return () => { cancelled = true; clearTimeout(t); };
    // eslint-disable-next-line react-hooks/exhaustive-deps
  }, [specKey, valid.ok]);
  const current = quote && quote.key === specKey ? quote : null;
  const confirmedPrice = current?.status === "ok" ? current.priceCents : null;

  /* A capacity failure can surface two ways: the debounced quote says so, or
     the quote said yes and the node filled up before "Use this custom server"
     (confirmCustom*Action then answers `needsSales`). Either way, for THIS spec
     the path forward is the sales request, not a dead end. Keyed by spec so
     moving a slider to something that fits clears it. */
  const [buildNeedsSales, setBuildNeedsSales] = useState<{ key: string; reason: string } | null>(null);
  const salesFromBuild = buildNeedsSales && buildNeedsSales.key === specKey ? buildNeedsSales.reason : null;
  const capacityBad = (current?.status === "ok" && !current.capacityOk) || salesFromBuild !== null;
  const capacityReason =
    salesFromBuild ?? (current?.status === "ok" ? current.capacityReason : undefined) ?? CUSTOM_PLAN_NEEDS_SALES_REASON;
  const canContinue = valid.ok && current?.status === "ok" && current.capacityOk && !salesFromBuild;

  const [requestOpen, setRequestOpen] = useState(false);
  const salesRef = useRef<HTMLDivElement>(null);
  const openRequest = () => {
    setRequestOpen(true);
    // The request form sits under the price panel; on a phone that's off-screen.
    requestAnimationFrame(() => salesRef.current?.scrollIntoView({ behavior: "smooth", block: "nearest" }));
  };

  const [busy, setBusy] = useState(false);
  const [err, setErr] = useState<string | null>(null);
  async function build() {
    if (!canContinue || busy) return;
    setBusy(true); setErr(null);
    try {
      if (isGame) {
        const res = await confirmCustomGamePlanAction({
          // The headcount the customer told us — stored as the tier's
          // RECOMMENDED player count (GamePlan.slots), never enforced as a cap.
          ...spec, gameFamily: family!, players,
        });
        if (res.needsSales) { setBuildNeedsSales({ key: specKey, reason: res.error ?? CUSTOM_PLAN_NEEDS_SALES_REASON }); openRequest(); return; }
        if (!res.ok || !res.tier) { setErr(res.error ?? "Couldn't set up that custom server."); return; }
        const t = res.tier;
        applyCustomTier(family!, {
          id: t.gamePlanId,
          // Display name only — the DB row's name carries the family key as a
          // suffix for admin views, which reads oddly in the customer's cart.
          name: `Custom · ${t.cpuCores} vCPU / ${gb(t.ramMB)} GB`,
          ramMB: t.ramMB, cpuCores: t.cpuCores, diskGB: t.diskGB,
          slots: t.slots,
          monthlyCents: t.priceCents,
          termMonths: t.termMonths,
          // Same pairing app/dashboard/deploy/page.tsx gives a catalog tier:
          // the intro rate, and the regular rate it renews at.
          introMonthlyCents: t.introPriceCents,
          introRenewalMonthlyCents: t.introPriceCents !== null ? t.priceCents : null,
          termMonthlyCents: t.termMonthlyCents,
        });
      } else {
        const res = await confirmCustomPlanAction(spec);
        if (res.needsSales) { setBuildNeedsSales({ key: specKey, reason: res.error ?? CUSTOM_PLAN_NEEDS_SALES_REASON }); openRequest(); return; }
        if (!res.ok || !res.plan) { setErr(res.error ?? "Couldn't set up that custom server."); return; }
        const p = res.plan;
        applyCustomPlan({
          id: p.id, slug: "custom", name: `Custom · ${p.cpuCores} vCPU / ${gb(p.ramMB)} GB`,
          cpuCores: p.cpuCores, ramMB: p.ramMB, diskGB: p.diskGB, bandwidthTB: p.bandwidthTB,
          monthlyCents: p.priceCents,
          // Same basis as the catalogue plans' `effectiveMonthlyCents` (the
          // monthly-term rate); the per-term figures ride in termMonthlyCents.
          effectiveMonthlyCents: p.termMonthlyCents[1] ?? p.priceCents,
          // Same pairing app/dashboard/deploy/page.tsx gives a catalog plan.
          introMonthlyCents: p.introPriceCents,
          introRenewalMonthlyCents: p.introPriceCents !== null ? p.priceCents : null,
          termMonthlyCents: p.termMonthlyCents,
        });
      }
      onBuilt();
    } catch {
      setErr("Couldn't set up that custom server — please try again.");
    } finally {
      setBusy(false);
    }
  }

  /* Why the sales card should be the headline rather than a footnote. Any of
     these means "a person should size this", so the card offers the ticket. */
  const atAnyMax = spec.cpuCores >= ceiling.maxCpuCores || spec.ramMB >= ceiling.maxRamMB || spec.diskGB >= ceiling.maxDiskGB;
  const salesReason: string | null =
      playerInfo?.overCeiling ? `~${players} players needs more than our self-serve maximum (${ceiling.maxCpuCores} vCPU · ${gb(ceiling.maxRamMB)} GB · ${ceiling.maxDiskGB} GB).`
    : capacityBad ? capacityReason
    : atAnyMax ? "You're at our self-serve maximum on at least one resource."
    : null;

  const salesHref = useMemo(() => {
    const lines = [
      "Custom server request (from the deploy wizard)",
      `Product: ${isGame ? `Game server — ${familyName ?? family}` : "Cloud VPS"}`,
      ...(isGame ? [`Players: ~${players}`] : []),
      `Spec I was looking at: ${spec.cpuCores} vCPU / ${gb(spec.ramMB)} GB RAM / ${spec.diskGB} GB disk`,
      `Billing term: ${terms.find((t) => t.months === o.termMonths)?.label ?? `${o.termMonths} months`}`,
      ...(salesReason ? [`Note: ${salesReason}`] : []),
      "",
      "What I need: ",
    ];
    return `/contact?topic=custom&message=${encodeURIComponent(lines.join("\n"))}`;
  }, [isGame, familyName, family, players, spec, terms, o.termMonths, salesReason]);

  // The slider "+$X/mo" indicators always measure from the SLIDER's own floor
  // (its minimum position) — that's what "Included" vs "+$X/mo" means on a
  // slider regardless of VPS or game.
  const extraCpu = Math.max(0, spec.cpuCores - floor.cpuCores);
  const extraRamGb = Math.max(0, gb(spec.ramMB - floor.ramMB));
  const extraDisk = Math.max(0, spec.diskGB - floor.diskGB);
  const shownPrice = confirmedPrice ?? preview;
  const termLabel = terms.find((t) => t.months === o.termMonths)?.label ?? "";
  const isMonthly = o.termMonths === 1;
  /* The intro (first-term) price. While the sliders move it comes from the same
     pure function createCustom*Plan stores on the row
     (computeCustomIntroPriceCents), fed by the same intro terms. Once the
     authoritative quote lands, the server's own figure replaces it, exactly as
     confirmedPrice replaces the preview. Checkout then charges this row through
     orderQuote / gameOrderQuote like any catalog plan. */
  const shownIntro = current?.status === "ok" ? current.introPriceCents : computeCustomIntroPriceCents(preview, cfg.intro);
  const hasIntro = shownIntro !== null;
  const termMonthly = current?.status === "ok"
    ? (hasIntro ? current.introTermMonthlyCents?.[o.termMonths] : current.termMonthlyCents[o.termMonths])
    : undefined;

  /* The sales-request ticket (feature: "carry the specs they want"). Built from
     exactly what is on screen: the spec, the headcount for a game, the term, and
     the self-serve price if the server has confirmed one. Framed as a request
     for review. Nothing is provisioned or charged by sending it, and the body
     says so, because the customer reads this ticket too. */
  const productLabel = isGame ? `${familyName ?? family} server` : "Cloud VPS";
  const ticketSummary = `${productLabel} · ${specLine(spec)}${isGame ? ` · ~${players} players` : ""}`;
  const ticketSubject =
    `Custom server request (needs review): ${spec.cpuCores} vCPU / ${gb(spec.ramMB)} GB RAM / ${spec.diskGB} GB disk` +
    (isGame ? ` · ${familyName ?? family}` : "");
  const ticketBody = [
    "Custom server request from the deploy wizard. This needs a person to review it: nothing has been provisioned or charged yet.",
    "",
    `Product: ${isGame ? `Game server, ${familyName ?? family}` : "Cloud VPS"}`,
    ...(isGame ? [`Expected players: ~${players}`] : []),
    `vCPU: ${spec.cpuCores}`,
    `Memory: ${gb(spec.ramMB)} GB RAM`,
    `NVMe disk: ${spec.diskGB} GB`,
    `Billing term: ${termLabel || `${o.termMonths} months`}`,
    // USD, not the visitor's display currency: this is read by staff, and
    // every charge is in USD.
    ...(confirmedPrice !== null
      ? [`Self-serve price shown: ${usd(confirmedPrice)}/mo USD` +
         (hasIntro ? ` (first ${isMonthly ? "month" : "term"} ${usd(shownIntro!)}/mo)` : "")]
      : []),
    // A plain fact for the ticket, not the builder's call-to-action sentence.
    ...(capacityBad
      ? ["Why it came to sales: this size couldn't be placed automatically when requested, so it needs a person to provision it."]
      : salesReason ? [`Why it came to sales: ${salesReason}`] : []),
  ].join("\n");

  // The itemised BREAKDOWN below, unlike the sliders above, has to sum to
  // `shownPrice` exactly. For VPS that's `floor` (the formula's own base) — for
  // a game it's `cfg.anchor` (this family's own real top tier, what
  // computeCustomGamePlanPriceCents actually extends from; `floor.priceCents`
  // for a game is the VPS-Max anti-undercut number, not a real price this
  // family ever charged). `platformMin` absorbs the rare case where the
  // anti-undercut clamp is what's actually setting the price (a cheap family
  // right at its floor) — kept a single line rather than pretending that
  // dollar amount is CPU, RAM or disk when it isn't.
  const breakdownBase = isGameCfg(cfg) ? cfg.anchor : floor;
