 * Re-validates guardrails AND capacity from scratch (a client-supplied price/spec is
 * never trusted for money — mirrors every other quote→place split in this codebase)
 * before writing anything, then hands off to `createCustomPlanRow`.
 */
export async function createCustomPlan(spec: CustomPlanSpec): Promise<CreatedCustomPlan> {
  const quote = await customPlanQuote(spec);
  if (!quote.ok) throw new CustomPlanError(quote.reason);
  const cap = await customPlanCapacityCheck(spec);
  if (!cap.ok) throw new CustomPlanCapacityError(cap.reason ?? CUSTOM_PLAN_NEEDS_SALES_REASON);
  return createCustomPlanRow(spec, quote.priceCents, quote.floor.bandwidthTB, quote.introPriceCents);
}

export type CreatedCustomGamePlan = {
  // Same quote→place split every other money path in this codebase uses (see
  // createCustomPlan/customPlanQuote above) — one function computes the price,
  // both the read-only quote (customGamePlanQuote, called by the wizard while a
  // customer is still moving sliders) and this real write path call it, so they
  // can never independently drift from each other.
  const quote = await customGamePlanQuote(opts.gameFamily, opts.spec);
  if (!quote.ok) throw new CustomPlanError(quote.reason);
  const cap = await customPlanCapacityCheck(opts.spec);
  if (!cap.ok) throw new CustomPlanCapacityError(cap.reason ?? CUSTOM_PLAN_NEEDS_SALES_REASON);

  const plan = await createCustomPlanRow(opts.spec, quote.priceCents, quote.floor.bandwidthTB, null);
  const gp = await db.gamePlan.create({
    data: {
  return cents < priceCents ? cents : null;
}

/**
 * Customer-facing wording for a valid spec the capacity check can't place
 * (lib/custom-plan.ts `customPlanCapacityCheck`). Lives here, in the pure
 * module, so the deploy wizard can use the same sentence. Owner's brief
 * (2026-09-29): the old "the host is at capacity" / "no node currently has
 * room" wording "makes us look smaller". The honest fact is narrower: this size
 * can't be auto-deployed from the wizard right now. A person can still size and
 * provision it, which is what the builder's "Request this build" ticket is for.
 */
export const CUSTOM_PLAN_NEEDS_SALES_REASON =
  "This build is bigger than we can deploy automatically right now. Send it to our team and we'll set it up with you.";

/** Sane platform-wide ceiling — deliberately generous (nothing in the premade
 *  catalog approaches this), but not infinite: a real physical node has to be
 *  able to hold it. Admin-tunable via lib/settings.ts (custom_plan_max_*). */

