/**
 * Worker sweeps added by the signup-fixes batch (2026-10-06). Registered in
 * worker/index.ts registerSweeps().
 *
 *  - setupQueueSweep: places "queued for setup" orders (lib/setup-queue.ts)
 *    once a node in their region has room, through the SAME guards a fresh
 *    order goes through (fleet RAM ceiling, region-bound scheduler incl. the
 *    live RAM guard in enforce mode, node disk pool). Oldest first, one region
 *    at a time, so a small amount of freed RAM goes to whoever waited longest.
 *  - activityPruneSweep: deletes ActivityEvent rows past activity_retention_days.
 */
import { db } from "../lib/db";
import { capacityCheckRamMB, diskCapacityCheck } from "../lib/capacity";
import { scheduleNodeDetailed } from "../lib/node-capacity";
import { effectiveDiskGB } from "../lib/extra-disk";
import { releaseQueuedServer } from "../lib/setup-queue";
import { pruneActivity, recordActivity } from "../lib/activity-events";
import { getSettingInt } from "../lib/settings";

export async function setupQueueSweep(): Promise<void> {
  let queued;
  try {
    queued = await db.server.findMany({
      where: { setupQueuedAt: { not: null }, status: "PENDING" },
      orderBy: { setupQueuedAt: "asc" },
      take: 25,
      select: {
        id: true, hostname: true, userId: true, setupQueuedAt: true, setupQueueRegion: true, extraDiskGB: true,
        plan: { select: { ramMB: true, diskGB: true } },
        gamePlan: { select: { ramMB: true } },
        osTemplate: { select: { vmid: true, baseVmid: true } },
      },
    });
  } catch (e) {
    console.error("[setup-queue] list failed", e);
    return;
  }
  for (const s of queued) {
    try {
      const ramMB = s.gamePlan?.ramMB ?? s.plan.ramMB;
      const region = s.setupQueueRegion ?? undefined;
      const fleet = await capacityCheckRamMB(ramMB);
      if (!fleet.ok) continue;
      const placed = await scheduleNodeDetailed(ramMB, {
        region,
        templateVmid: s.osTemplate ? s.osTemplate.baseVmid ?? s.osTemplate.vmid : null,
        strict: false,
        quiet: true,
        userId: s.userId,
        product: s.gamePlan ? "game" : "vps",
      });
      if (!placed.node) continue;
      const disk = await diskCapacityCheck(placed.node.id, effectiveDiskGB(s.plan.diskGB, s.extraDiskGB ?? 0));
      if (!disk.ok) continue;
      const released = await releaseQueuedServer(s.id, placed.node.id);
      if (released) {
        const waitedMin = s.setupQueuedAt ? Math.round((Date.now() - s.setupQueuedAt.getTime()) / 60_000) : null;
        console.log(`[setup-queue] ${s.hostname} placed on ${placed.node.name} after ${waitedMin} min; PROVISION enqueued`);
        await recordActivity({
          type: "wizard.queued",
          userId: s.userId,
          serverId: s.id,
          label: `Queued order placed on a node after ${waitedMin} min; setup started`,
          data: { released: true, node: placed.node.name, waitedMin },
        });
      }
    } catch (e) {
      console.error("[setup-queue] place failed", s.id, e);
    }
  }
}

export async function activityPruneSweep(): Promise<void> {
  try {
    const days = await getSettingInt("activity_retention_days", 180);
    const n = await pruneActivity(days);
    if (n) console.log(`[activity] pruned ${n} event(s) older than ${days} days`);
  } catch (e) {
    console.error("[activity] prune failed", e);
  }
}

