/**
 * Payment records for the activity timeline (owner, 2026-10-06: "I want those
 * payment records logged"). Every payment event — checkout opened, cancelled /
 * expired, succeeded, pending, failed (decline code, 3-D Secure), refunds,
 * disputes, PayPal / Coinbase, local methods, wallet top-ups, renewals and
 * dunning steps — becomes one `ActivityEvent` row (category "payment") written
 * through lib/activity-events.ts.
 *
 * Pure mapping functions (stripe event/object -> ActivityInput) live here so
 * they are unit-tested without Stripe or a DB (test/payment-events.test.ts).
 * This module never imports lib/stripe.ts (lib/stripe.ts imports it), and has no
 * server-only import — the worker's renewal sweep uses it.
 *
 * Idempotency: webhook rows carry dedupeKey "stripe:<event id>", so a Stripe
 * redelivery is ignored. Rows that can be written by TWO sources (the worker
 * logging its own off-session charge AND the webhook seeing the same
 * PaymentIntent; an admin refund AND the charge.refunded webhook) share an
 * object-level key ("pi:<id>:succeeded", "refund:<re id>") so they are written once.
 */
import type Stripe from "stripe";
import { recordActivity, type ActivityInput, type ActivityType, type PaymentOutcome } from "./activity-events";

/** Which product a Nxeon checkout paid for, from our own metadata keys. */
export function purposeFromMetadata(md: Record<string, string> | null | undefined): string {
  const m = md ?? {};
  if (m.nxeonOrder) return "vps_order";
  if (m.nxeonGameOrder) return "game_order";
  if (m.nxeonHostOrder) return "hosting_order";
  if (m.nxeonEmailOrder) return "email_order";
  if (m.nxeonDomainOrder) return "domain_order";
  if (m.nxeonResize) return "resize";
  if (m.nxeonDiskExpand) return "disk_expand";
  if (m.nxeonDedicatedIp) return "dedicated_ip";
  if (m.nxeonCardSetup) return "card_setup";
  if (m.nxeonChargeKey?.startsWith("renew:")) return "renewal";
  if (m.nxeonChargeKey) return "auto_recharge";
  return "topup";
}

const PURPOSE_LABEL: Record<string, string> = {
  vps_order: "VPS order",
  game_order: "game server order",
  hosting_order: "web hosting order",
  email_order: "business email order",
  domain_order: "domain order",
  resize: "server resize",
  disk_expand: "disk upgrade",
  dedicated_ip: "dedicated IPv4",
  card_setup: "saving a card",
  renewal: "renewal",
  auto_recharge: "wallet auto-recharge",
  topup: "wallet top-up",
};

export function purposeLabel(p: string): string {
  return PURPOSE_LABEL[p] ?? p.replace(/_/g, " ");
}

function money(cents: number | null | undefined, currency: string | null | undefined): string {
  if (typeof cents !== "number") return "";
  const cur = (currency ?? "usd").toUpperCase();
  return `${(cents / 100).toFixed(2)} ${cur}`;
}

/** Method of a Checkout Session without another API call. */
export function sessionMethod(s: Pick<Stripe.Checkout.Session, "payment_method_types" | "metadata">): string {
  const local = s.metadata?.nxeonLocalPay;
  if (local) return local;
  const types = s.payment_method_types ?? [];
  if (types.length === 1) return types[0];
  if (types.length === 0) return "card";
  return types.includes("card") ? "card" : types.join("+");
}

/** Human reason for a failed PaymentIntent / card error (no free-text from the customer). */
export function failureReason(code: string | null | undefined, declineCode: string | null | undefined): string {
  const c = declineCode || code || "";
  const map: Record<string, string> = {
    insufficient_funds: "insufficient funds",
    card_declined: "card declined",
    generic_decline: "declined by the bank",
    do_not_honor: "declined by the bank (do not honor)",
    expired_card: "card expired",
    incorrect_cvc: "wrong CVC",
    incorrect_number: "wrong card number",
    processing_error: "processing error",
    lost_card: "card reported lost",
    stolen_card: "card reported stolen",
    fraudulent: "blocked as suspected fraud",
    authentication_required: "3-D Secure required",
    payment_intent_authentication_failure: "3-D Secure failed or abandoned",
    card_not_supported: "card type not supported",
    currency_not_supported: "currency not supported by the card",
    transaction_not_allowed: "transaction not allowed by the bank",
    withdrawal_count_limit_exceeded: "card limit exceeded",
    card_velocity_exceeded: "card limit exceeded",
  };
  return map[c] ?? (c ? c.replace(/_/g, " ") : "unknown reason");
}

/** Is this failure the 3-D Secure / authentication class (vs a plain decline)? */
export function isAuthFailure(code: string | null | undefined, declineCode?: string | null): boolean {
  return code === "authentication_required" || code === "payment_intent_authentication_failure" || declineCode === "authentication_required";
}

type Mapped = Omit<ActivityInput, "userId"> & { userId?: string | null; stripeCustomer?: string | null; paymentIntentId?: string | null };

function base(type: ActivityType, outcome: PaymentOutcome, extra: Partial<Mapped>): Mapped {
  return { type, outcome, provider: "stripe", ...extra };
}

/**
 * Pure: map a Stripe webhook event to the activity row it should produce
 * (userId resolved separately), or null when the event is not a payment
 * record we keep. Exported for tests.
 */
export function stripeEventToActivity(event: Stripe.Event): Mapped | null {
  const dedupeKey = `stripe:${event.id}`;
  const at = new Date(event.created * 1000);
  switch (event.type) {
    case "checkout.session.completed":
    case "checkout.session.async_payment_succeeded":
    case "checkout.session.async_payment_failed":
    case "checkout.session.expired": {
      const s = event.data.object as Stripe.Checkout.Session;
      if (s.mode === "setup") return null; // saving a card is not a payment
      const purpose = purposeFromMetadata(s.metadata as Record<string, string>);
      const method = sessionMethod(s);
      const amount = s.amount_total ?? null;
      const currency = s.currency ?? null;
      const country = s.customer_details?.address?.country ?? null;
      const common = {
        dedupeKey, createdAt: at, method, amountCents: amount, currency, country, reference: s.id,
        userId: s.metadata?.nxeonUserId ?? null,
        stripeCustomer: typeof s.customer === "string" ? s.customer : s.customer?.id ?? null,
        paymentIntentId: typeof s.payment_intent === "string" ? s.payment_intent : s.payment_intent?.id ?? null,
        data: { purpose, mode: s.mode, uiMode: s.ui_mode ?? null, paymentStatus: s.payment_status, creditUsdCents: s.metadata?.nxeonCreditUsdCents ? Number(s.metadata.nxeonCreditUsdCents) : null },
      } satisfies Partial<Mapped>;
      if (event.type === "checkout.session.expired") {
        return base("payment.checkout_expired", "expired", { ...common, label: `Checkout for ${purposeLabel(purpose)} expired unpaid (${money(amount, currency)}, ${method})` });
      }
      if (event.type === "checkout.session.async_payment_failed") {
        return base("payment.failed", "failed", { ...common, label: `${method} payment for ${purposeLabel(purpose)} was refused by the bank (${money(amount, currency)})`, data: { ...common.data, reason: "delayed payment failed" } });
      }
      if (event.type === "checkout.session.completed" && s.payment_status === "unpaid") {
        return base("payment.pending", "pending", { ...common, label: `${method} payment for ${purposeLabel(purpose)} started, waiting for the bank (${money(amount, currency)})` });
      }
      return base("payment.succeeded", "succeeded", { ...common, label: `Paid ${money(amount, currency)} by ${method} for ${purposeLabel(purpose)}` });
    }
    case "payment_intent.payment_failed":
    case "payment_intent.requires_action":
    case "payment_intent.succeeded": {
      const pi = event.data.object as Stripe.PaymentIntent;
      const md = (pi.metadata ?? {}) as Record<string, string>;
      const offSession = !!md.nxeonChargeKey;
      // Checkout-session PaymentIntents' success is already the session event.
      if (event.type === "payment_intent.succeeded" && !offSession) return null;
      const purpose = purposeFromMetadata(md);
      const err = pi.last_payment_error;
      const pm = err?.payment_method ?? null;
      const method = pm?.type ?? (pi.payment_method_types?.length === 1 ? pi.payment_method_types[0] : "card");
      const country = pm?.card?.country ?? pm?.billing_details?.address?.country ?? null;
      const common = {
        createdAt: at, method, amountCents: pi.amount, currency: pi.currency, country, reference: pi.id,
        userId: md.nxeonUserId ?? null,
        stripeCustomer: typeof pi.customer === "string" ? pi.customer : pi.customer?.id ?? null,
        paymentIntentId: pi.id,
      } satisfies Partial<Mapped>;
      if (event.type === "payment_intent.succeeded") {
        return base(purpose === "renewal" ? "payment.renewal" : "payment.succeeded", "succeeded", {
          ...common, dedupeKey: `pi:${pi.id}:succeeded`,
          label: `Charged saved ${method} ${money(pi.amount, pi.currency)} for ${purposeLabel(purpose)}`,
          data: { purpose, offSession: true },
        });
      }
      if (event.type === "payment_intent.requires_action") {
        return base("payment.requires_action", "requires_action", {
          ...common, dedupeKey,
          label: `${purposeLabel(purpose)} needs 3-D Secure confirmation (${money(pi.amount, pi.currency)})`,
          data: { purpose, offSession, nextAction: pi.next_action?.type ?? null },
        });
      }
      const auth = isAuthFailure(err?.code, err?.decline_code);
      return base(auth ? "payment.requires_action" : "payment.failed", auth ? "requires_action" : "failed", {
        ...common,
        dedupeKey: offSession ? `pi:${pi.id}:failed` : dedupeKey,
        label: `${method} payment ${money(pi.amount, pi.currency)} for ${purposeLabel(purpose)} failed: ${failureReason(err?.code, err?.decline_code)}`,
        data: {
          purpose, offSession,
          code: err?.code ?? null, declineCode: err?.decline_code ?? null, errorType: err?.type ?? null,
          threeDS: auth, cardBrand: pm?.card?.brand ?? null, funding: pm?.card?.funding ?? null,
          reason: failureReason(err?.code, err?.decline_code),
        },
      });
    }
    case "charge.refunded": {
      const ch = event.data.object as Stripe.Charge;
      const latest = ch.refunds?.data?.[0];
      return base("payment.refunded", "refunded", {
        createdAt: at,
        dedupeKey: latest?.id ? `refund:${latest.id}` : dedupeKey,
        method: ch.payment_method_details?.type ?? "card",
        amountCents: latest?.amount ?? ch.amount_refunded,
        currency: ch.currency,
        country: ch.payment_method_details?.card?.country ?? ch.billing_details?.address?.country ?? null,
        reference: latest?.id ?? ch.id,
        userId: (ch.metadata as Record<string, string> | null)?.nxeonUserId ?? null,
        stripeCustomer: typeof ch.customer === "string" ? ch.customer : ch.customer?.id ?? null,
        paymentIntentId: typeof ch.payment_intent === "string" ? ch.payment_intent : ch.payment_intent?.id ?? null,
        label: `Refunded ${money(latest?.amount ?? ch.amount_refunded, ch.currency)}${ch.refunded ? " (full)" : " (partial)"}`,
        data: { chargeId: ch.id, totalRefundedCents: ch.amount_refunded, full: ch.refunded, refundReason: latest?.reason ?? null },
      });
    }
    case "charge.dispute.created":
    case "charge.dispute.closed":
    case "charge.dispute.updated": {
      const d = event.data.object as Stripe.Dispute;
      const opened = event.type === "charge.dispute.created";
      if (event.type === "charge.dispute.updated") return null;
      return base(opened ? "payment.dispute_opened" : "payment.dispute_closed", "disputed", {
        createdAt: at, dedupeKey,
        amountCents: d.amount, currency: d.currency, reference: d.id,
        paymentIntentId: typeof d.payment_intent === "string" ? d.payment_intent : d.payment_intent?.id ?? null,
        label: opened
          ? `Dispute opened: ${money(d.amount, d.currency)}, reason ${String(d.reason).replace(/_/g, " ")}`
          : `Dispute closed: ${d.status.replace(/_/g, " ")} (${money(d.amount, d.currency)})`,
        data: { reason: d.reason, status: d.status, chargeId: typeof d.charge === "string" ? d.charge : d.charge?.id ?? null, evidenceDueBy: d.evidence_details?.due_by ?? null },
      });
    }
    default:
      return null;
  }
}

/** Stripe webhook event types this module records — the owner must enable each on the endpoint. */
export const STRIPE_LOGGED_EVENTS = [
  "checkout.session.completed",
  "checkout.session.async_payment_succeeded",
  "checkout.session.async_payment_failed",
  "checkout.session.expired",
  "payment_intent.payment_failed",
  "payment_intent.requires_action",
  "payment_intent.succeeded",
  "charge.refunded",
  "charge.dispute.created",
  "charge.dispute.closed",
] as const;

export type UserResolver = (m: Mapped) => Promise<string | null>;

/**
 * Record a Stripe webhook event (after signature verification). `resolveUser`
 * fills the user when our metadata didn't carry it (customer id lookup, the
 * PaymentIntent's Checkout Session). Never throws.
 */
export async function recordStripeEvent(event: Stripe.Event, resolveUser?: UserResolver): Promise<"created" | "duplicate" | "error" | "skipped"> {
  let mapped: Mapped | null;
  try {
    mapped = stripeEventToActivity(event);
  } catch (e) {
    console.error("[payment-events] map failed", event.type, e);
    return "error";
  }
  if (!mapped) return "skipped";
  let userId = mapped.userId ?? null;
  if (!userId && resolveUser) {
    try {
      userId = await resolveUser(mapped);
    } catch {
      userId = null;
    }
  }
  const { stripeCustomer: _c, paymentIntentId: _p, ...row } = mapped;
  return recordActivity({ ...row, userId });
}

/** Checkout opened (called from every session create in lib/stripe*.ts). Never throws. */
export async function recordCheckoutOpened(s: Stripe.Checkout.Session, extra?: { userId?: string | null }): Promise<void> {
  if (s.mode === "setup") return;
  const purpose = purposeFromMetadata(s.metadata as Record<string, string>);
  const method = sessionMethod(s);
  await recordActivity({
    type: "payment.checkout_opened",
    outcome: "opened",
    provider: "stripe",
    userId: extra?.userId ?? s.metadata?.nxeonUserId ?? null,
    method,
    amountCents: s.amount_total ?? null,
    currency: s.currency ?? null,
    reference: s.id,
    dedupeKey: `checkout-opened:${s.id}`,
    label: `Opened ${method} checkout for ${purposeLabel(purpose)} (${money(s.amount_total, s.currency)})`,
    data: { purpose, uiMode: s.ui_mode ?? null, hosted: s.ui_mode === "hosted" },
  });
}

/** One helper for every non-Stripe-webhook payment row (PayPal, Coinbase, wallet, worker). */
export async function recordPayment(p: {
  type: ActivityType;
  outcome: PaymentOutcome;
  provider: "stripe" | "paypal" | "coinbase" | "wallet";
  userId: string | null;
  method?: string | null;
  amountCents?: number | null;
  currency?: string | null;
  country?: string | null;
  reference?: string | null;
  dedupeKey?: string | null;
  serverId?: string | null;
  label: string;
  data?: Record<string, unknown>;
}): Promise<void> {
  await recordActivity({ ...p, currency: p.currency ?? "usd" });
}

/** Map a classified off-session charge result (lib/stripe-charge-errors.ts) to a payment row. */
export function offSessionOutcome(kind: string): { type: ActivityType; outcome: PaymentOutcome } {
  if (kind === "ok" || kind === "succeeded") return { type: "payment.renewal", outcome: "succeeded" };
  if (kind === "requires_action") return { type: "payment.requires_action", outcome: "requires_action" };
  return { type: "payment.failed", outcome: "failed" };
}

