import Link from "next/link";
import { STRIPE_LOGGED_EVENTS } from "@/lib/payment-events";
import { requireArea } from "@/lib/rbac";
import { db } from "@/lib/db";
import { PageHeader, StatCard, Badge, fmtMoney, timeAgo } from "@/components/ui/primitives";

async function attemptCardRenewal(opts: {
  server: DueServer;
  charge: RenewalCharge;
  cardCents: number;
  newExpiry: Date;
  now: Date;
  cfg: DunningConfig;
  /** Destination country the VAT was charged for; passed through to the invoice. */
  taxCountry?: string;
}): Promise<CardRenewalOutcome> {
  const { server, charge, cardCents, newExpiry, now, cfg, taxCountry } = opts;
  const user = server.user;
  const periodStart = server.expiresAt!;
  const marker = renewalChargeMarker(server.id, periodStart);
  const idempotencyKey = `nxeon_renew_${server.id}_${periodStart.getTime()}_a${server.dunningStage}_${cardCents}`;
  const cardLabel = savedCardLabel(user) ?? "your saved card";

  const result = await chargeSavedCardOffSession({
    user,
    amountCents: cardCents,
    description: `Renewal: ${charge.label} (${server.hostname})`,
    marker,
    idempotencyKey,
    metadata: {
      nxeonServerId: server.id,
      nxeonPeriodStart: periodStart.toISOString(),
      nxeonKind: "renewal",
    },
  });

  if (result.ok) {
    // Exactly what Stripe took, not what we asked for — a replayed intent can carry
    // an older amount and the ledger must match the bank, not our intent.
    const credited = await creditOffSessionCharge({
      userId: server.userId,
      amountCents: result.amountCents,
      description: `Card payment for ${server.hostname} renewal (${cardLabel})`,
      paymentIntentId: result.paymentIntentId,
      // No invoice for the card leg: `commitRenewal` issues ONE paid invoice for
      // the whole renewal, and a second document for the card portion would
      // double-count the same revenue.
    });
    const outcome = await commitRenewal({ server, charge, newExpiry, taxCountry });

    // The receipt is tied to the CREDIT, not the renewal: `creditOffSessionCharge`
    // returns false on the P2002 that means "already credited", so a replayed
    // capture cannot email the same customer a second receipt for one charge.
    if (credited) {
      await mail(
        user.email,
        user.id,
        emails.paymentReceipt(
          fmtUsd(result.amountCents),
          `${charge.label} — ${server.hostname}`,
          user.cardLast4 ?? "",
        ),
        // ACCOUNT tier — a receipt is the one mail from this sweep a customer may
        // legitimately opt out of. Everything else here is CRITICAL by default.
        "receipt",
      );
    }

    if (outcome === "insufficient") {
      // The card paid, the wallet was credited, and the debit STILL failed — the
      // customer spent the credit between our split read and the transaction. The
      // money is not lost, it is sitting in their wallet; re-run shortly rather
      // than charging again (the marker replays this same capture, so the next
      // pass cannot take a second payment) and do NOT count it as a dunning
      // failure, because nothing about their card went wrong.
      console.error(
        `[billing] ${server.hostname}: card captured ${fmtUsd(result.amountCents)} but the wallet debit fell short — retrying shortly`,
      );
      await rescheduleAttempt(server, new Date(now.getTime() + TRANSIENT_RETRY_MS));
      return {
        renewed: false,
        kind: "walletDebitRaced",
        message: `Card captured $${(result.amountCents / 100).toFixed(2)} and credited the wallet, but the renewal debit lost a race with another spend — it will retry shortly and cannot double-charge (the capture is guarded by a permanent marker).`,
      };
    }
    // `outcome === "already"` falls through to the same success return as
    // "renewed": someone else's pass advanced this exact period between our
    // capture and our commit, which only the CAS on `expiresAt` can detect. The
    // card was still charged and the wallet still credited for real money, so
    // this is success from every caller's point of view — not a decline, and not
    // a reason to retry (a retry here would be the actual double-charge this
    // whole function exists to prevent).
    if (outcome === "renewed") {
      console.log(
        `[billing] renewed ${server.hostname} until ${newExpiry.toISOString()} (card ${fmtUsd(result.amountCents)}${result.replayed ? ", replayed" : ""})`,
      );
    }
    return { renewed: true, amountCents: result.amountCents, replayed: result.replayed };
  }

  if (result.kind === "transient") {
    // Our side or Stripe's side wobbled. Never a dunning event: a misclassified
    // transient costs a delayed renewal, a misclassified decline costs a paid-up
    // customer their server. The attempt counter is untouched.
    console.warn(`[billing] transient charge error for ${server.hostname}: ${result.message}`);
    await rescheduleAttempt(server, new Date(now.getTime() + TRANSIENT_RETRY_MS));
    return { renewed: false, kind: "transient", message: result.message };
  }

  if (result.kind === "unavailable") {
    // `hasChargeableCard` already proved Stripe is configured and both ids are
    // present, and `walletSplit` keeps the amount above Stripe's floor — so the
    // only ways here are the saved PaymentMethod itself being dead at Stripe:
    // `resource_missing` (gone) or "may not be used again" (recorded unattached /
    // detached — the 2026-10-01 incident, previously misread as transient and
    // retried hourly in silence). Not a decline; nothing to retry until a NEW
    // card is saved. `retireUnusableCard` marks the row unusable, clears the
    // mirror (so the portal stops claiming a card is on file and no sweep tries
    // it again), grants PLATFORM_FAULT_GRACE_DAYS before any suspension — this
    // is our fault, so warnings come first — and sends the first re-add notice.
    await retireUnusableCard({
      server,
      cardCents,
      now,
      reason: result.reason ?? "not_reusable",
      message: result.message,
    });
    return { renewed: false, kind: "unavailable", message: result.message };
  }

  if (result.kind === "requires_action") {
    // 3-D Secure. Off-session there is no browser to satisfy the challenge, so the
    // answer is a hosted Checkout link: the customer completes the bank step on
    // Stripe's own page, the money lands as wallet credit and the next sweep
    // renews from the wallet. This is NOT a decline — nothing about the card is
    // wrong — so it must never consume a retry, or a customer who simply hasn't

    // wrong — so it must never consume a retry, or a customer who simply hasn't
    // opened their email yet would be dunned toward suspension for their bank's
    // security policy.
    let payUrl = server.dunningPayUrl;
    if (!payUrl) {
      payUrl = await createOutstandingCheckout({
        user,
        amountCents: cardCents,
        hostname: server.hostname,
        serverId: server.id,
      });
      if (payUrl) {
        await db.server.update({ where: { id: server.id }, data: { dunningPayUrl: payUrl } });
        await mail(
          user.email,
          user.id,
          emails.paymentActionRequired(server.hostname, fmtUsd(cardCents), payUrl),
        );
        await notify(
          server.userId,
          `${server.hostname} — your bank needs to confirm the payment`,
          `Your card issuer asked for an extra verification step for ${fmtUsd(cardCents)}. Confirming it finishes the renewal. Nothing is suspended.`,
          `/dashboard/servers/${server.id}`,
        );
      }
    }
    // Re-check daily rather than hourly: the challenge does not move, and the same
    // link is already in their inbox. `dunningPayUrl` being set is what stops the
    // email repeating for this period; `clearStaleDunning`/`commitRenewal` clear it.
    server.dunningPayUrl = payUrl;
    await rescheduleAttempt(server, new Date(now.getTime() + MIN_RETRY_GAP_MS));
    console.log(`[billing] ${server.hostname} awaiting 3-D Secure confirmation for ${fmtUsd(cardCents)}`);
    return {
      renewed: false,
      kind: "requiresAction",
      message: payUrl
        ? `Your bank requires additional verification (3-D Secure) — a confirmation link has been emailed to the customer: ${payUrl}`
        : "Your bank requires additional verification (3-D Secure), and no hosted checkout link could be created to complete it off-session.",
    };
  }

  // Hard decline — the issuer said no. This is the only outcome that spends an
  // attempt and moves the customer along the dunning sequence.
  await recordDeclinedAttempt({ server, cardCents, now, cfg, reason: result.message });
  return { renewed: false, kind: "declined", message: result.message, code: result.code };
}

/**
 * The PayPal analogue of `attemptCardRenewal`, for a customer with a vaulted
 * PayPal method but no saved card. Same money model (charge the shortfall,
 * credit the wallet for exactly what was taken, `commitRenewal` debits the
 * FULL renewal from the wallet) and the same dunning cadence/schedule — only
 * gated separately behind `renewals_paypal_fallback_enabled` (see
 * `renewDueServer`'s `paypalInPlay`) since the underlying charge path
 * (`chargeVaultedPayPalOffSession`) has not yet been exercised against a real
 * PayPal charge from this codebase.
 *
 * IDEMPOTENCY differs from the card path: PayPal's Orders API has no
 * equivalent to Stripe's `paymentIntents.list({customer, ...})` metadata
 * search, so there is no durable pre-flight "did we already charge this
 * period" lookup at PayPal's end. Instead, `marker` is embedded in the
 * WalletTransaction description written by `creditOffSessionCharge` on
 * success, and checked here FIRST — a crash between "PayPal captured" and
 * "we recorded the credit" therefore still cannot double-charge, because a
 * retried pass finds its own prior credit before ever calling PayPal again.
 * `idempotencyKey` still drives PayPal's own short-lived request-replay
 * protection for the case where two sweeps genuinely overlap within it.
 *
 * @returns true when the term was actually extended.
 */
async function attemptPayPalRenewal(opts: {

 *
 * Two independent idempotency guards, because this moves real money on a timer
 * that retries:
 *  1. `marker` — pre-flight lookup of a live PaymentIntent for this exact purpose.
 *     Survives forever, catches the crash-after-capture window.
 *  2. `idempotencyKey` — Stripe replays the identical request instead of charging
 *     twice when two sweeps overlap. Only good for 24h, hence guard 1.
 */
export async function chargeSavedCardOffSession(opts: {
  user: CardUser;
  amountCents: number;
  description: string;
  marker: string;
  idempotencyKey: string;
  metadata?: Record<string, string>;
}): Promise<OffSessionResult> {
  const { user, amountCents, description, marker, idempotencyKey } = opts;
  if (!stripeConfigured()) return { ok: false, kind: "unavailable", message: "Stripe is not configured" };
  if (!user.stripeCustomerId || !user.stripePaymentMethodId) {
    return { ok: false, kind: "unavailable", message: "No saved card" };
  }
  // `walletSplit` already keeps the card leg at or above Stripe's floor; this is
  // the belt-and-braces check so a future caller can't send a rejectable amount.
  if (amountCents < STRIPE_MIN_CENTS) {
    return { ok: false, kind: "unavailable", message: `Below Stripe minimum (${STRIPE_MIN_CENTS}c)` };
  }

  // Guard 1: did we already charge for this purpose?
  try {
    const existing = await findChargeByMarker(user.stripeCustomerId, marker);
    if (existing?.status === "succeeded") {
      return {
        ok: true,
        paymentIntentId: existing.id,
        amountCents: existing.amount_received || existing.amount,
        replayed: true,

