/**
 * Web-request wrapper around lib/activity-events.ts `recordActivity()`: adds the
 * truncated client IP, country, device/OS/browser and the impersonating admin
 * (if any) from the current request. Server actions and route handlers call
 * `recordRequestActivity()`; the worker and scripts call `recordActivity()`
 * directly. Never throws.
 */
import "server-only";
import { headers } from "next/headers";
import { clientIp, UNKNOWN_IP } from "./rate-limit";
import { countryFromIp } from "./geo-ip";
import { parseUserAgent } from "./ua-parse";
import { impersonating } from "./auth";
import { recordActivity, type ActivityInput } from "./activity-events";

type HeaderLike = { get(name: string): string | null };

/** Context from a request's headers (IP is truncated by recordActivity, never stored whole). */
export function requestContextFrom(h: HeaderLike): Pick<ActivityInput, "ip" | "country" | "deviceType" | "os" | "browser"> {
  const ip = clientIp(h);
  const ua = parseUserAgent(h.get("user-agent"));
  const country = (h.get("cf-ipcountry") || h.get("x-nxeon-country") || "").toUpperCase() || countryFromIp(ip === UNKNOWN_IP ? null : ip);
  return {
    ip: ip === UNKNOWN_IP ? null : ip,
    country: country && /^[A-Z]{2}$/.test(country) ? country : null,
    deviceType: ua.deviceType ?? null,
    os: ua.os ?? null,
    browser: ua.browser ?? null,
  };
}

export async function recordRequestActivity(input: ActivityInput, opts?: { headers?: HeaderLike }): Promise<void> {
  try {
    let ctx: ReturnType<typeof requestContextFrom> | Record<string, never> = {};
    try {
      ctx = requestContextFrom(opts?.headers ?? (await headers()));
    } catch {
      ctx = {};
    }
    let actorAdminId: string | null = null;
    try {
      const imp = await impersonating();
      actorAdminId = imp ? imp.admin.id : null;
    } catch {
      actorAdminId = null;
    }
    await recordActivity({ ...ctx, actorAdminId, ...input, country: input.country ?? (ctx as { country?: string | null }).country ?? null });
  } catch {
    /* telemetry never breaks the caller */
  }
}

