import { NextRequest, NextResponse } from "next/server";
import { currentUser, impersonating } from "@/lib/auth";
import { checkRateLimit } from "@/lib/rate-limit";
import { isClientActivityType, recordActivityBatch, type ActivityInput } from "@/lib/activity-events";
import { clientEventLabel } from "@/lib/activity-client-labels";
import { requestContextFrom } from "@/lib/activity-request";

/**
 * First-party activity beacon (components/ActivityBeacon.tsx → lib/activity-client.ts).
 *
 * - Signed-in customers only; nothing is recorded for guests or while an admin
 *   is impersonating (staff browsing must not pollute the customer's journey).
 * - Only catalogue types marked `client: true` are accepted, so a browser can
 *   never forge a payment, auth or server-side action row.
 * - Batched (max 25 events per request) and rate-limited per account.
 * - The server builds every label from the sanitized fields; client text is
 *   never shown as-is. Always answers 204 so a beacon never retries or errors.
 */
export const runtime = "nodejs";

const MAX_EVENTS = 25;

export async function POST(req: NextRequest) {
  const none = new NextResponse(null, { status: 204 });
  try {
    const user = await currentUser();
    if (!user || (await impersonating())) return none;
    // 40 batches and ~400 events a minute per account is far above a real person.
    if (!checkRateLimit(`activity:${user.id}`, { max: 40, windowMs: 60_000 }).ok) return none;
    const raw = await req.text();
    if (raw.length > 64_000) return none;
    let body: unknown;
    try {
      body = JSON.parse(raw);
    } catch {
      return none;
    }
    const list = Array.isArray((body as { events?: unknown[] })?.events) ? (body as { events: unknown[] }).events.slice(0, MAX_EVENTS) : [];
    const ctx = requestContextFrom(req.headers);
    const visitorId = req.cookies.get("nx_vid")?.value ?? null;
    const now = Date.now();
    const rows: ActivityInput[] = [];
    for (const e of list) {
      if (!e || typeof e !== "object") continue;
      const ev = e as Record<string, unknown>;
      if (!isClientActivityType(ev.type)) continue;
      const data = ev.data && typeof ev.data === "object" && !Array.isArray(ev.data) ? (ev.data as Record<string, unknown>) : null;
      // client timestamps are accepted only within the last 10 minutes (beacon flush delay)
      const at = typeof ev.at === "number" && ev.at <= now && now - ev.at < 10 * 60_000 ? new Date(ev.at) : undefined;
      rows.push({
        type: ev.type,
        userId: user.id,
        visitorId,
        sessionId: typeof ev.sessionId === "string" ? ev.sessionId : null,
        route: typeof ev.route === "string" ? ev.route : null,
        referrer: typeof ev.referrer === "string" ? ev.referrer : null,
        durationMs: typeof ev.durationMs === "number" ? ev.durationMs : null,
        serverId: typeof ev.serverId === "string" ? ev.serverId : null,
        label: clientEventLabel(ev.type, data),
        data,
        createdAt: at,
        ...ctx,
      });
    }
    if (rows.length) await recordActivityBatch(rows);
  } catch {
    /* never surface */
  }
  return none;
}
EOF

