/**
 * Server-built labels for client-sent activity events (pure; unit-tested).
 * The browser only sends structured fields; this turns them into the sentence
 * the admin timeline shows, so no client-supplied free text is ever displayed.
 */
import { ACTIVITY_TYPES, type ActivityType } from "./activity-events";

const FIELD_NAMES: Record<string, string> = {
  service: "product",
  product: "product",
  game: "game",
  plan: "plan",
  term: "billing term",
  region: "region",
  os: "operating system",
  addon: "add-on",
  coupon: "coupon",
  custom: "custom build",
  variant: "server type",
  disk: "extra disk",
  payment_method: "payment method",
  wallet: "use wallet",
  hosting_plan: "hosting plan",
  email_plan: "email plan",
  domain: "domain",
};

function short(v: unknown, max = 60): string {
  if (v === null || v === undefined) return "";
  const s = typeof v === "string" ? v : typeof v === "number" || typeof v === "boolean" ? String(v) : JSON.stringify(v);
  return s.length > max ? `${s.slice(0, max)}…` : s;
}

export function clientEventLabel(type: ActivityType, data: Record<string, unknown> | null): string {
  const d = data ?? {};
  switch (type) {
    case "wizard.step":
      return `Deploy wizard (${short(d.product, 20) || "?"}): reached step ${short(d.step, 30)}${typeof d.stepIndex === "number" ? ` (#${d.stepIndex + 1})` : ""}`;
    case "wizard.field": {
      const f = FIELD_NAMES[String(d.field)] ?? short(d.field, 30);
      const on = d.on === false ? " removed" : "";
      return `Deploy wizard (${short(d.product, 20) || "?"}): ${f}${on} → ${short(d.label ?? d.value)}`;
    }
    case "wizard.open":
      return `Opened the deploy wizard${d.product ? ` (${short(d.product, 20)})` : ""}`;
    case "wizard.submit":
      return `Deploy wizard (${short(d.product, 20) || "?"}): pressed ${short(d.action, 30) || "Pay / Deploy"}`;
    case "wizard.abandon":
      return `Left the deploy wizard at ${short(d.step, 30) || "?"} (${short(d.product, 20) || "?"})`;
    case "payment.checkout_closed":
      return `Closed the ${short(d.method, 20) || "payment"} form without paying`;
    case "error.shown":
      return `Saw an error${d.where ? ` on ${short(d.where, 40)}` : ""}: ${short(d.error, 140)}`;
    case "error.stale_client":
      return `Page was out of date after an update${d.autoReload ? " (refreshed automatically)" : " (asked to refresh)"}`;
    case "action.ui":
      return `${short(d.action, 60) || "Dashboard action"}${d.target ? ` · ${short(d.target, 40)}` : ""}`;
    case "page.view":
      return `Viewed ${short(d.title, 60) || "a page"}`;
    default:
      return ACTIVITY_TYPES[type].label;
  }
}
