"use client";

/**
 * Browser side of the first-party activity beacon. Events are queued in memory
 * and flushed in batches (every 5 s, at 20 queued, or on pagehide via
 * sendBeacon) to /api/activity. A per-tab cap stops a runaway loop from sending
 * more than 300 events. Never throws; tracking failures are silent.
 *
 * Privacy: callers pass STRUCTURED choices only (field + value ids/labels the
 * customer picked from a list). Never pass typed text, passwords, file
 * contents, card data or keystrokes — the server also drops such keys.
 */
type ClientEvent = {
  type: string;
  route?: string;
  referrer?: string | null;
  durationMs?: number;
  serverId?: string | null;
  data?: Record<string, unknown>;
  at: number;
  sessionId?: string | null;
};

const ENDPOINT = "/api/activity";
const FLUSH_MS = 5000;
const FLUSH_AT = 20;
const TAB_CAP = 300;

let queue: ClientEvent[] = [];
let sent = 0;
let timer: ReturnType<typeof setTimeout> | null = null;
let listening = false;
let enabled = true;

/** Turned off by the beacon component when the viewer is staff impersonating. */
export function setActivityEnabled(on: boolean) {
  enabled = on;
}

function sessionId(): string | null {
  try {
    return sessionStorage.getItem("nx_sid");
  } catch {
    return null;
  }
}

function flush(useBeacon = false) {
  if (timer) {
    clearTimeout(timer);
    timer = null;
  }
  if (!queue.length) return;
  const batch = queue.splice(0, 25);
  const body = JSON.stringify({ events: batch });
  try {
    if (useBeacon && typeof navigator !== "undefined" && navigator.sendBeacon) {
      navigator.sendBeacon(ENDPOINT, new Blob([body], { type: "application/json" }));
    } else {
      void fetch(ENDPOINT, { method: "POST", body, headers: { "content-type": "application/json" }, keepalive: true, credentials: "same-origin" }).catch(() => undefined);
    }
  } catch {
    /* ignore */
  }
  if (queue.length) flush(useBeacon);
}

function ensureListeners() {
  if (listening || typeof window === "undefined") return;
  listening = true;
  window.addEventListener("pagehide", () => flush(true));
  document.addEventListener("visibilitychange", () => {
    if (document.visibilityState === "hidden") flush(true);
  });
}

export function trackActivity(type: string, fields: Omit<ClientEvent, "type" | "at"> = {}) {
  try {
    if (!enabled || typeof window === "undefined") return;
    if (sent >= TAB_CAP) return;
    sent++;
    ensureListeners();
    queue.push({ type, at: Date.now(), sessionId: sessionId(), route: window.location.pathname, ...fields });
    if (queue.length >= FLUSH_AT) flush();
    else if (!timer) timer = setTimeout(() => flush(), FLUSH_MS);
  } catch {
    /* ignore */
  }
}

/** Last field value per (product, field), so re-renders don't log the same choice twice. */
const lastField = new Map<string, string>();

/** A deploy-wizard choice that matters (product, game, plan, region, OS, add-on, coupon...). */
export function trackWizardField(product: string, field: string, value: unknown, extra?: { label?: string; on?: boolean }) {
  const v = value === null || value === undefined ? "" : String(value);
  const key = `${product}:${field}${extra?.on !== undefined ? `:${v}` : ""}`;
  const sig = `${v}|${extra?.on ?? ""}`;
  if (lastField.get(key) === sig) return;
  lastField.set(key, sig);
  trackActivity("wizard.field", { data: { product, field, value: v.slice(0, 80), label: extra?.label?.slice(0, 80), on: extra?.on } });
}

/** An error message the customer actually saw (validation, order error, payment error). */
export function trackErrorShown(error: string, where?: string) {
  if (!error) return;
  trackActivity("error.shown", { data: { error: error.slice(0, 200), where } });
}
EOF

