  const key = `${product}:${field}${extra?.on !== undefined ? `:${v}` : ""}`;
  const sig = `${v}|${extra?.on ?? ""}`;
  if (lastField.get(key) === sig) return;
  lastField.set(key, sig);
  trackActivity("wizard.field", { data: { product, field, value: v.slice(0, 80), label: extra?.label?.slice(0, 80), on: extra?.on } });
}

/** An error message the customer actually saw (validation, order error, payment error). */
export function trackErrorShown(error: string, where?: string) {
  if (!error) return;
  trackActivity("error.shown", { data: { error: error.slice(0, 200), where } });
}
