/**
 * A deploy replaces .next's static chunk files under new content hashes. A
 * browser tab left open across that deploy still holds JS referencing the
 * OLD hashes, so the next code-split import 404s — a webpack ChunkLoadError
 * (or, on some browsers/bundler paths, "Failed to fetch dynamically imported
 * module"). This isn't a real app bug, just a stale asset reference, and a
 * plain reload fixes it since the page then fetches the current build.
 * Confirmed live 2026-09-02 on /admin/inbox right after a promote.
 */
export function isChunkLoadError(error: Error): boolean {
  return (
    error.name === "ChunkLoadError" ||
    /Loading chunk [\d]+ failed/i.test(error.message) ||
    /Failed to fetch dynamically imported module/i.test(error.message) ||
    /Importing a module script failed/i.test(error.message)
  );
}

const RELOAD_AT_KEY = "nxeon:chunk-reload-at";
const RELOAD_COOLDOWN_MS = 15_000;

/** Reloads once per cooldown window — if the reload doesn't fix it (a real
 *  outage, not a stale chunk), this stops retrying and lets the normal error
 *  UI show instead of silently looping reloads forever. */
export function reloadForChunkErrorOnce(): boolean {
  if (typeof window === "undefined") return false;
  const last = Number(sessionStorage.getItem(RELOAD_AT_KEY) ?? 0);
  const now = Date.now();
  if (now - last < RELOAD_COOLDOWN_MS) return false;
  sessionStorage.setItem(RELOAD_AT_KEY, String(now));
  window.location.reload();
  return true;
}
"use client";

import { useEffect, useState } from "react";
import Link from "next/link";
import { isChunkLoadError, reloadForChunkErrorOnce } from "@/lib/chunk-error";

export function ErrorState({
  error,
  reset,
  context,
  home = "/",
  homeLabel = "Go home",
}: {
  error: Error & { digest?: string };
  reset: () => void;
  context: string;
  home?: string;
  homeLabel?: string;
}) {
  const [reloading, setReloading] = useState(false);

  useEffect(() => {
    // Best-effort report to the server error pipeline.
    try {
      fetch("/api/log", {
        method: "POST",
        headers: { "content-type": "application/json" },
        body: JSON.stringify({
          context,
          message: error?.message,
          digest: error?.digest,
          stack: error?.stack,
          path: typeof window !== "undefined" ? window.location.pathname : undefined,
        }),
        keepalive: true,
      }).catch(() => {});
    } catch {
      /* ignore */
    }
  }, [error, context]);

  useEffect(() => {
    if (!isChunkLoadError(error)) return;
    if (reloadForChunkErrorOnce()) setReloading(true);
  }, [error]);

  if (reloading) {
    return (
      <div className="grid min-h-[70vh] place-items-center px-4 py-16">
        <p className="text-sm text-slate-400">Updating…</p>
      </div>
    );
  }

  return (
    <div className="grid min-h-[70vh] place-items-center px-4 py-16">
      <div className="card max-w-md text-center">
        <div className="mx-auto mb-4 grid h-12 w-12 place-items-center rounded-full bg-red-500/10 text-2xl">⚠️</div>
        <h1 className="mb-2 text-xl font-semibold">Something went wrong</h1>
        <p className="mb-1 text-sm text-slate-400">
          We hit an unexpected error and our team has been notified. You can retry, or head back.
        </p>
        {error?.digest && (
          <p className="mb-5 font-mono text-xs text-slate-600">ref: {error.digest}</p>
        )}
        <div className="flex items-center justify-center gap-3">
          <button onClick={() => reset()} className="btn-primary">
            Try again
          </button>
          <Link href={home} className="btn-secondary">
            {homeLabel}
          </Link>
        </div>
      </div>
    </div>
  );
}

