"use client";

import { useEffect, useRef, useState } from "react";
import { isStaleClientError, reloadForChunkErrorOnce } from "@/lib/chunk-error";
import { STALE_CLIENT_EVENT } from "@/lib/stale-client";
import { trackActivity } from "@/lib/activity-client";

/**
 * Global stale-client handler (signup-friction report 2026-10-06: "Failed to find
 * Server Action" 253 times on a deploy day). After a deploy, a tab opened on the
 * previous build calls Server Action ids / JS chunks the server no longer has.
 *
 * Detects it from (a) unhandled errors and promise rejections and (b) the
 * `nx:stale-client` event that catch blocks raise via reportIfStaleClient().
 * Then:
 *   - SAFE (the customer hasn't typed anything on this page yet): refresh
 *     automatically, at most once per 15 s (same cooldown as chunk errors), so a
 *     click that failed is simply retried on the current build;
 *   - otherwise: a friendly "A new version is available" bar with a Refresh
 *     button, never a scary error, and nothing they typed is thrown away
 *     without their say-so.
 * Mounted once in app/layout.tsx so it covers marketing, dashboard and admin.
 */
export function StaleClientGuard() {
  const [show, setShow] = useState(false);
  const typed = useRef(false);
  const handled = useRef(false);

  useEffect(() => {
    const onInput = (e: Event) => {
      const t = e.target as HTMLElement | null;
      if (t && (t.tagName === "INPUT" || t.tagName === "TEXTAREA" || t.isContentEditable)) typed.current = true;
    };
    const trigger = () => {
      if (handled.current) return;
      handled.current = true;
      const auto = !typed.current;
      trackActivity("error.stale_client", { data: { autoReload: auto } });
      if (auto && reloadForChunkErrorOnce()) return;
      setShow(true);
    };
    const onError = (e: ErrorEvent) => { if (isStaleClientError(e.error ?? { message: e.message })) trigger(); };
    const onRejection = (e: PromiseRejectionEvent) => { if (isStaleClientError(e.reason)) { trigger(); e.preventDefault(); } };
    window.addEventListener("input", onInput, true);
    window.addEventListener("error", onError);
    window.addEventListener("unhandledrejection", onRejection);
    window.addEventListener(STALE_CLIENT_EVENT, trigger);
    return () => {
      window.removeEventListener("input", onInput, true);
      window.removeEventListener("error", onError);
      window.removeEventListener("unhandledrejection", onRejection);
      window.removeEventListener(STALE_CLIENT_EVENT, trigger);
    };
  }, []);

  if (!show) return null;
  return (
    <div role="status" aria-live="polite"
         style={{ position: "fixed", left: 16, right: 16, bottom: 16, zIndex: 2147483000, display: "flex", justifyContent: "center", pointerEvents: "none" }}>
      <div style={{
        pointerEvents: "auto", display: "flex", flexWrap: "wrap", alignItems: "center", gap: 12, maxWidth: 560, width: "100%",
        padding: "12px 14px", borderRadius: 12, border: "1px solid rgba(123,63,239,0.45)",
        background: "linear-gradient(100deg, rgba(14,22,48,0.97), rgba(30,20,64,0.97))", color: "#e8ecff",
        boxShadow: "0 10px 30px rgba(0,0,0,0.45)", fontSize: 14, lineHeight: 1.45,
      }}>
        <span style={{ flex: "1 1 240px" }}>
          <b style={{ display: "block", color: "#fff" }}>A new version of Nxeon is available</b>
          Refresh to continue. Anything you were doing will work on the new version.
        </span>
        <button type="button" onClick={() => window.location.reload()}
                style={{ flex: "none", height: 38, padding: "0 16px", borderRadius: 9, border: 0, cursor: "pointer", fontWeight: 700, color: "#fff",
                         background: "linear-gradient(100deg,#3b6be8,#7b3fef)" }}>
          Refresh
        </button>
        <button type="button" onClick={() => setShow(false)} aria-label="Dismiss"
                style={{ flex: "none", height: 38, padding: "0 10px", borderRadius: 9, border: "1px solid rgba(255,255,255,0.2)", background: "transparent", color: "#cfd6f5", cursor: "pointer" }}>
          Later
        </button>
      </div>
    </div>
  );
}
