const set = useCallback(<K extends keyof Order>(k: K, v: Order[K]) => {
  setO((p) => ({ ...p, [k]: v }));
}, []);

const chooseService = useCallback((k: ServiceKey) => {
  // Re-clicking the service tile that's already active must be a no-op —
  // this used to unconditionally reseed (fresh plan/term/hostname/addons),
  // so a customer who'd already configured VPS and tapped the "Cloud VPS"
  // tile again (e.g. from the rail, or a stray double-tap) lost everything
  // they'd picked below. Returning the SAME object (not a shallow copy)
  // also skips the reseed effects that key off a new `o` reference.
  setO((p) => (p.service === k ? p : seedOrder(p, cat, k)));
}, [cat]);

/* Choosing a family seeds its cheapest tier and its default loader, so the
   order is immediately priceable; the customer changes what they care about. */
const chooseGame = useCallback((family: string) => {
  // Same idempotency as chooseService above, one level down: re-picking the
  // family that's already selected must not reset the tier/variant/config
  // the customer already chose on the Server step back to the cheapest
  // tier and empty config.
  setO((p) => {
    if (p.gameFamily === family) return p;
    const g = cat.games.find((x) => x.family === family);
    if (!g) return p;
    const cheapest = [...g.tiers].sort((a, b) => a.monthlyCents - b.monthlyCents)[0];
    return {
      ...p,
      gameFamily: family,
      gamePlanId: cheapest?.id ?? null,
      gameVariant: g.defaultVariant,
      subdomain: "",
      // A previous game's field values (e.g. Valheim's SERVER_PASS) must never
      // leak into a different family's config — keys rarely collide, but when
      // they do (two families both using SERVER_PASS) a stale value would
      // silently carry over instead of the customer setting their own.
      gameConfig: { ...g.defaultConfig },
    };
  });
}, [cat]);

const applyCustomPlan = useCallback((p: PlanOption) => {
  setCustomPlans([{ ...p, custom: true }]);
  setO((prev) => ({ ...prev, planId: p.id }));
}, []);
const applyCustomTier = useCallback((family: string, t: GameTier) => {
  setCustomTiers((prev) => ({ ...prev, [family]: [{ ...t, custom: true }] }));
  setO((prev) => (prev.gameFamily === family ? { ...prev, gamePlanId: t.id } : prev));
}, []);

const toggleAddon = useCallback((k: string) => {
