new='''  /* ── first-party activity: every wizard choice that matters ─────────────
     One observer instead of a call in every setter: diff the order 800 ms
     after it settles and log the fields that changed (product, game, plan,
     term, region, OS, add-ons, disk, coupon, server type, wallet). Structured
     values only — never the hostname, server name, game config or anything
     typed as free text. lib/activity-client.ts batches + rate-caps the beacon. */
  const prevTracked = useRef<Order | null>(null);
  useEffect(() => {
    const t = setTimeout(() => {
      const prev = prevTracked.current;
      prevTracked.current = o;
      if (!prev || cat.guest) return;
      const product = o.service ?? "none";
      const f = (field: string, a: unknown, b: unknown, label?: string) => {
        if (a === b || b === null || b === undefined || b === "") return;
        trackWizardField(product, field, b, { label });
      };
      f("service", prev.service, o.service);
      f("game", prev.gameFamily, o.gameFamily, cat.games.find((g) => g.family === o.gameFamily)?.name);
      f("plan", prev.planId, o.planId, (cat.plans.find((p) => p.id === o.planId) ?? customPlans.find((p) => p.id === o.planId))?.name);
      if (o.gamePlanId !== prev.gamePlanId && o.gamePlanId) {
        const g = cat.games.find((x) => x.family === o.gameFamily);
        const tier = g?.tiers.find((x) => x.id === o.gamePlanId) ?? customTiers[o.gameFamily ?? ""]?.find((x) => x.id === o.gamePlanId);
        trackWizardField(product, "plan", o.gamePlanId, { label: tier?.name });
      }
      f("term", prev.termMonths, o.termMonths, `${o.termMonths} month${o.termMonths === 1 ? "" : "s"}`);
      f("region", prev.region, o.region, cat.regions.find((r) => r.key === o.region)?.name);
      f("os", prev.osId, o.osId, cat.oses.find((x) => x.id === o.osId)?.name);
      f("variant", prev.gameVariant, o.gameVariant);
      f("disk", prev.diskGb, o.diskGb, `${o.diskGb} GB extra`);
      f("hosting_plan", prev.hostingPlanId, o.hostingPlanId, cat.hosting.find((h) => h.id === o.hostingPlanId)?.name);
      f("email_plan", prev.emailPlanId, o.emailPlanId, cat.email.find((h) => h.id === o.emailPlanId)?.name);
      if (prev.useWallet !== o.useWallet) trackWizardField(product, "wallet", o.useWallet ? "on" : "off");
      if (prev.couponCode !== o.couponCode && o.couponCode.trim().length >= 3) trackWizardField(product, "coupon", o.couponCode.trim().toUpperCase().slice(0, 32));
      for (const a of o.addons) if (!prev.addons.includes(a)) trackWizardField(product, "addon", a, { on: true, label: cat.addons.find((x) => x.key === a)?.label ?? a });
      for (const a of prev.addons) if (!o.addons.includes(a)) trackWizardField(product, "addon", a, { on: false, label: cat.addons.find((x) => x.key === a)?.label ?? a });
    }, 800);
    return () => clearTimeout(t);
    // eslint-disable-next-line react-hooks/exhaustive-deps
  }, [o]);

  const plan = useMemo(() => cat.plans.find((p) => p.id === o.planId) ?? null, [cat.plans, o.planId]);'''
