type FunnelRow = { product: string; step: string; stepIndex: number; type: string; sessionId: string | null; createdAt: Date; errorMessage: string | null; errorCode: string | null; detail?: string | null };
type FieldRow = { createdAt: Date; type: string; data: unknown };

/** Pure: summarise one customer's wizard journey per product (unit-tested). */
export function summariseWizard(funnel: FunnelRow[], fields: FieldRow[]): WizardProgress[] {
