    if (p && p !== "none" && !byProduct.has(p)) byProduct.set(p, []);
  }
  const out: WizardProgress[] = [];
  for (const [product, rowsUnsorted] of byProduct) {
    const rows = [...rowsUnsorted].sort((a, b) => a.createdAt.getTime() - b.createdAt.getTime());
    const steps = rows.filter((r) => r.type === "step");
    let furthest: FunnelRow | null = null;
    for (const r of steps) if (!furthest || r.stepIndex > furthest.stepIndex) furthest = r;
    const completed = rows.filter((r) => r.type === "complete").length;
    const sessions = new Set(rows.map((r) => r.sessionId ?? `t:${r.createdAt.toISOString().slice(0, 13)}`)).size;
    // last session: the session id of the newest row
    const last = rows[rows.length - 1];
    const lastSession = last ? rows.filter((r) => (r.sessionId ?? null) === (last.sessionId ?? null)) : [];
    const lastCompleted = lastSession.some((r) => r.type === "complete");
    let lastStep: FunnelRow | null = null;
    for (const r of lastSession) if (r.type === "step" && (!lastStep || r.stepIndex >= lastStep.stepIndex)) lastStep = r;

