      .filter((f) => (f.data as { product?: string } | null)?.product === product)
      .sort((a, b) => a.createdAt.getTime() - b.createdAt.getTime());
    const addons = new Set<string>();
    let abandonStep: string | null = null;
    for (const f of productFields) {
      const d = (f.data ?? {}) as { field?: string; value?: string; label?: string; on?: boolean; step?: string };
