    for (const r of rows.filter((x) => x.type === "select")) {
      const v = (selectDetail(r.detail) as { value?: unknown } | null)?.value;
      if (v !== undefined && !lastConfig[r.step]) lastConfig[r.step] = String(v);
    }
    if (addons.size) lastConfig.addons = [...addons].join(", ");
