    out.push({
      product,
      sessions,
      furthestStep: furthest?.step ?? null,
      furthestStepIndex: furthest?.stepIndex ?? -1,
      reachedPayment: steps.some((s) => /payment/i.test(s.step)),
      completed,
      lastSeenAt: lastSeen.length ? new Date(Math.max(...lastSeen.map((d) => d.getTime()))) : new Date(0),
      droppedAt: lastCompleted ? null : lastStep?.step ?? abandonStep,
      lastConfig,
      lastErrors: rows.filter((r) => r.type === "error").slice(-3).map((r) => r.errorMessage ?? r.errorCode ?? "error"),
    });
  }
  return out.sort((a, b) => b.lastSeenAt.getTime() - a.lastSeenAt.getTime());
}

/** Per-product deploy-wizard progress for one customer (furthest step, last config, drop point). */
export async function loadWizardProgress(userId: string, days = 180): Promise<WizardProgress[]> {
  const since = new Date(Date.now() - days * 24 * 60 * 60 * 1000);
  const [funnelRaw, fields] = await Promise.all([
