    db.deployFunnelEvent.findMany({ where: { userId, createdAt: { gte: since } }, orderBy: { createdAt: "asc" }, take: 2000 }),
    db.activityEvent.findMany({
      where: { userId, createdAt: { gte: since }, type: { in: ["wizard.field", "wizard.abandon"] } },
      orderBy: { createdAt: "asc" },
