  ]);
  return summariseWizard(funnelRaw as unknown as FunnelRow[], fields);
}

/** Payment rows only — the "payments" view the owner asked for. */
export async function loadPaymentRecords(userId: string, limit = 100) {
  return db.activityEvent.findMany({ where: { userId, category: "payment" }, orderBy: { createdAt: "desc" }, take: Math.min(limit, 500) });
}

