export async function SecurityTab({ user }: { user: ClientCore }) {
  const [logins, sessions, visits, ownAudit, staffAudit, tokens, keys] = await Promise.all([
    db.auditLog.findMany({ where: { userId: user.id, action: { in: ["user.login", "user.login_failed", "user.password_reset_complete", "user.2fa_enabled", "user.2fa_disabled", "user.2fa_backup_code_used"] } }, orderBy: { createdAt: "desc" }, take: 30, select: { id: true, action: true, ip: true, detail: true, createdAt: true } }),
    db.userSession.findMany({ where: { userId: user.id }, orderBy: { lastSeenAt: "desc" }, take: 30 }),
    db.visit.findMany({ where: { userId: user.id }, orderBy: { createdAt: "desc" }, take: 120, select: { ip: true, country: true, city: true, path: true, kind: true, createdAt: true, browser: true, os: true } }),
    db.auditLog.findMany({ where: { userId: user.id }, orderBy: { createdAt: "desc" }, take: 40, select: { id: true, action: true, detail: true, ip: true, createdAt: true } }),
    db.auditLog.findMany({ where: { target: user.id, NOT: { userId: user.id } }, orderBy: { createdAt: "desc" }, take: 30, select: { id: true, action: true, detail: true, ip: true, createdAt: true, user: { select: { email: true } } } }),
    db.apiToken.findMany({ where: { userId: user.id }, orderBy: { createdAt: "desc" }, select: { id: true, name: true, prefix: true, scopes: true, lastUsedAt: true, expiresAt: true, revoked: true, createdAt: true } }),
    db.apiKey.findMany({ where: { userId: user.id }, orderBy: { createdAt: "desc" }, select: { id: true, name: true, prefix: true, scope: true, lastUsedAt: true, revokedAt: true, createdAt: true } }).catch(() => []),
  ]);
  const actorIds = [...new Set(ownAudit.map((a) => actingAdminId(a.detail)).filter(Boolean))] as string[];
  const actors = new Map((actorIds.length ? await db.user.findMany({ where: { id: { in: actorIds } }, select: { id: true, email: true } }) : []).map((u) => [u.id, u.email]));

  const ipMap = new Map<string, { country: string | null; city: string | null; lastSeen: Date; hits: number }>();
  for (const v of visits) {
    const cur = ipMap.get(v.ip);
    if (cur) cur.hits++;
    else {
      const geo = v.country || v.city ? { country: v.country, city: v.city } : geoLocateIp(v.ip);
      ipMap.set(v.ip, { country: geo?.country ?? null, city: geo?.city ?? null, lastSeen: v.createdAt, hits: 1 });
    }
  }
  const pages = visits.filter((v) => v.kind === "portal").slice(0, 20);
  const live = sessions.filter((s) => !s.revokedAt);

  return (
    <div className="space-y-4">
      <div className="grid gap-4 xl:grid-cols-3">
        <Card title="Security posture">
          <Fields cols={2}>
            <Field label="2FA">{user.totpEnabled ? <Badge tone="green">on</Badge> : <Badge tone="slate">off</Badge>}</Field>
            <Field label="Backup codes left">{user.totpEnabled ? user.backupCodes.length : "—"}</Field>
            <Field label="Email verified">{user.emailVerifiedAt ? fmtDateTime(user.emailVerifiedAt) : <Badge tone="amber">no</Badge>}</Field>
            <Field label="Session version" hint="bumps sign out every older session">{user.sessionVersion}</Field>
            <Field label="Live sessions">{live.length}</Field>
            <Field label="Account">{user.suspended ? <Badge tone="red">suspended</Badge> : "active"}</Field>
          </Fields>
          <p className="mt-3 text-xs text-slate-500">Reset 2FA, sign out everywhere and password reset are on the Actions tab.</p>
        </Card>

        <Card title={`Sessions (${sessions.length})`} className="xl:col-span-2">
          {sessions.length === 0 ? (
            <Empty>No sessions recorded.</Empty>
          ) : (
            <ul className="space-y-1 text-xs">
              {sessions.map((s) => (
                <li key={s.id} className={`flex flex-wrap justify-between gap-2 ${s.revokedAt ? "opacity-50" : ""}`}>
                  <span className="min-w-0 truncate">{s.userAgent ?? "unknown device"}</span>
                  <span className="font-mono text-slate-400">{s.ip ?? "—"}{s.location ? ` · ${s.location}` : ""}</span>
                  <span className="text-slate-500">seen {timeAgo(s.lastSeenAt)}{s.revokedAt ? ` · ended ${timeAgo(s.revokedAt)}` : ""}</span>
                </li>
              ))}
            </ul>

