export const dynamic = "force-dynamic";

/**
 * Customer 360 (2026-10-01 redesign) — URL tabs, only the active one loads:
 *   Profile & risk · Servers · Billing · Support · Activity & security · Partner & referrals · Actions
 * Every section of the previous single-scroll page is kept (client info, stats,
 * servers / hosting / email / domains, wallet + invoices, tickets + DMs, audit
 * trail, notes) and regrouped; new: risk signals, flags, card health, chats,
 * email log, sessions, API tokens, partner data and the account actions.
 *
 * RBAC is unchanged: `clients` admits SUPPORT to READ; every write control is
 * rendered only for ADMIN (canAct) and re-checked inside its action.
 */
export default async function AdminUserDetail({ params, searchParams }: { params: Promise<{ id: string }>; searchParams: Promise<{ tab?: string }> }) {
  const me = await requireArea("clients");
  const canAct = me.role === "ADMIN";
  const canMessage = await hasAreaAccess(me, "supportTickets");
  const { id } = await params;
  const sp = await searchParams;
  const user = await loadClientCore(id);
  if (!user) notFound();
  const tab = resolveClientTab(sp.tab);

  const [servers, renewalPrices, lifetime, openTickets, risk] = await Promise.all([
    db.server.findMany({
      where: { userId: id, status: { not: "DELETING" } },
      include: { plan: true, gamePlan: { select: { name: true, priceCents: true, termMonths: true } }, dedicatedIp: { select: { id: true } } },
    }),
    currentRenewalPrices(),
    realLifetimeSpendCents(id),
    db.ticket.count({ where: { userId: id, status: { not: "CLOSED" } } }),
    loadRisk(user),
  ]);
  const mrr = fleetMrrCents(await withGrantLive(servers), renewalPrices);
  const creatorIds = await loadCreatorUserIds([user.id]);
  const flags = clientFlags(user);
  const base = `/admin/users/${user.id}`;

  return (
    <div className="space-y-5">
      <header className="card flex flex-wrap items-center justify-between gap-4">
        <div className="flex min-w-0 items-center gap-4">
          <div className="flex h-14 w-14 shrink-0 items-center justify-center rounded-2xl border border-white/[0.08] bg-gradient-to-br from-accent-blue/20 to-brand-500/20 text-xl font-bold text-brand-300" aria-hidden>
            {user.name.slice(0, 1).toUpperCase()}
          </div>
          <div className="min-w-0">
            <div className="flex flex-wrap items-center gap-2">
              <h1 className="text-xl font-bold tracking-tight"><UserName name={user.name} creator={creatorIds.has(user.id)} /></h1>
              <Badge tone={user.role === "ADMIN" ? "brand" : "slate"}>{user.role.toLowerCase()}</Badge>
              {user.suspended && <Badge tone="red">suspended</Badge>}
              <span className="adm-pill" data-tone={risk.report.level === "high" ? "red" : risk.report.level === "medium" ? "amber" : "green"} title="Weight of the risk signals on the Profile tab — not a fraud probability">
                risk {risk.report.level}
              </span>
              {flags.map(({ flag, note }) => (
                <span key={note.id} title={flag.note || undefined}>
                  <Badge tone={flag.kind === "vip" ? "green" : "amber"}>{FLAG_LABELS[flag.kind]}</Badge>
                </span>
              ))}
            </div>
            <p className="mt-0.5 break-all text-sm text-slate-400">
              {user.email} · joined {user.createdAt.toISOString().slice(0, 10)}
            </p>
          </div>
        </div>
        <div className="flex flex-wrap items-center gap-2">
          {canMessage && user.role !== "ADMIN" && <MessageCustomerButton userId={user.id} />}
          {canAct ? (
            <>
              <CreditForm userId={user.id} />
              {user.role !== "ADMIN" && <ImpersonateButton userId={user.id} email={user.email} />}
            </>
          ) : (
            <p className="text-xs text-slate-500">Read-only — account actions require an admin account.</p>
          )}
        </div>
      </header>

      <dl className="grid grid-cols-2 gap-3 sm:grid-cols-3 xl:grid-cols-6">
        {[
          ["Wallet", fmtMoney(user.balanceCents)],
          ["Monthly spend", mrr > 0 ? `${fmtMoney(mrr)}/mo` : "$0.00"],
          ["Lifetime spend", fmtMoney(lifetime)],
          ["Servers", String(servers.length)],
          ["Other services", `${user._count.hostingAccounts} hosting · ${user._count.emailSubscriptions} email · ${user._count.domains} dom`],
          ["Open tickets", String(openTickets)],
        ].map(([k, v]) => (
          <div key={k} className="adm-kpi" style={{ minHeight: "auto" }}>
            <dt className="adm-kpi-label">{k}</dt>
            <dd className="adm-kpi-value" style={{ fontSize: k === "Other services" ? 13 : undefined }}>{v}</dd>
          </div>
        ))}
      </dl>

      <TabBar
        base={base}
        tabs={CLIENT_TABS.map((t) => ({ key: t.key, label: t.label, danger: "danger" in t ? t.danger : false }))}
        active={tab}
        label="Customer sections"
        badges={{ support: openTickets || undefined, profile: risk.report.level === "high" ? "!" : undefined }}
      />

      <Suspense key={tab} fallback={<div className="grid gap-4 xl:grid-cols-2"><PanelSkeleton rows={5} /><PanelSkeleton rows={5} /></div>}>
        {tab === "profile" && <ProfileTab user={user} canAct={canAct} />}
        {tab === "servers" && <ServersTab user={user} canAct={canAct} />}
        {tab === "billing" && <ClientBillingTab user={user} canAct={canAct} viewerRole={me.role} />}
        {tab === "support" && <SupportTab user={user} />}
        {tab === "security" && <SecurityTab user={user} />}
        {tab === "partner" && <PartnerTab user={user} />}
        {tab === "actions" && <ActionsTab user={user} canAct={canAct} />}
      </Suspense>

      <p className="text-xs text-slate-500">
        <Link href={`/admin/servers?owner=${user.id}`} className="hover:text-brand-300">This customer&apos;s servers in the fleet list →</Link>
      </p>
    </div>
  );
}
