import Link from "next/link";
import { db } from "@/lib/db";
import { Badge } from "@/components/ui/primitives";
import { Card, Empty, Field, Fields, fmtDateTime } from "@/components/admin/server360/ui";
import { ACTIVITY_CATEGORIES, type ActivityCategory } from "@/lib/activity-events";
import { loadActivityTimeline, loadPaymentRecords, loadWizardProgress, type TimelineItem } from "@/lib/activity-timeline";
import type { ClientCore } from "../core";

/**
 * Customer 360 → Activity timeline (signup-fixes 2026-10-06). One filterable
 * stream from lib/activity-timeline.ts: page visits, deploy-wizard steps and
 * choices, payments (with decline reasons), dashboard actions, errors the
 * customer saw, and sign-ins — plus the existing audit log, merged in.
 * Filters are plain links (?cat=, ?days=), so the page stays a server component.
 */
const CAT_LABEL: Record<ActivityCategory, string> = {
  page: "Pages",
  wizard: "Deploy wizard",
  payment: "Payments",
  action: "Actions",
  error: "Errors",
  auth: "Sign-in",
};
const CAT_TONE: Record<ActivityCategory, "brand" | "green" | "red" | "amber" | "slate" | "magenta"> = {
  page: "slate",
  wizard: "brand",
  payment: "green",
  action: "magenta",
  error: "red",
  auth: "amber",
};
const OUTCOME_TONE: Record<string, "brand" | "green" | "red" | "amber" | "slate"> = {
  succeeded: "green",
  refunded: "amber",
  failed: "red",
  disputed: "red",
  requires_action: "amber",
  expired: "slate",
  cancelled: "slate",
  opened: "brand",
  pending: "amber",
};

function money(cents: number | null | undefined, currency?: string | null) {
  if (typeof cents !== "number") return "—";
  return `${(cents / 100).toFixed(2)} ${(currency ?? "usd").toUpperCase()}`;
}

function dur(ms: number | null | undefined) {
  if (!ms || ms < 1000) return null;
  const s = Math.round(ms / 1000);
  return s < 60 ? `${s}s` : `${Math.floor(s / 60)}m ${s % 60}s`;
}

export async function ActivityTab({ user, cat, days }: { user: ClientCore; cat?: string; days?: string }) {
  const category = ACTIVITY_CATEGORIES.includes(cat as ActivityCategory) ? (cat as ActivityCategory) : null;
  const windowDays = [7, 30, 90, 180].includes(Number(days)) ? Number(days) : 30;
  const [items, progress, payments, counts] = await Promise.all([
    loadActivityTimeline(user.id, { categories: category ? [category] : undefined, days: windowDays, limit: 300 }),
    loadWizardProgress(user.id),
    loadPaymentRecords(user.id, 50),
    db.activityEvent.groupBy({ by: ["category"], where: { userId: user.id }, _count: { _all: true } }),
  ]);
  const base = `/admin/users/${user.id}?tab=activity`;
  const href = (c: ActivityCategory | null, d = windowDays) => `${base}${c ? `&cat=${c}` : ""}&days=${d}`;
  const countOf = (c: ActivityCategory) => counts.find((x) => x.category === c)?._count._all ?? 0;
  const actorIds = [...new Set(items.map((i) => i.actorAdminId).filter(Boolean))] as string[];
  const actors = new Map((actorIds.length ? await db.user.findMany({ where: { id: { in: actorIds } }, select: { id: true, email: true } }) : []).map((u) => [u.id, u.email]));
  const failedPayments = payments.filter((p) => p.outcome === "failed" || p.outcome === "requires_action").length;

  return (
    <div className="space-y-4">
      <Card title="Deploy wizard progress" sub="Furthest step, last configuration and where they stopped, per product (last 180 days)">
        {progress.length === 0 ? (
          <Empty>No deploy-wizard activity recorded for this customer.</Empty>
        ) : (
          <div className="grid gap-3 lg:grid-cols-2">
            {progress.map((p) => (
              <div key={p.product} className="rounded-xl border border-white/[0.08] bg-white/[0.02] p-3">
                <div className="mb-2 flex flex-wrap items-center gap-2">
                  <span className="text-sm font-semibold uppercase tracking-wide text-slate-200">{p.product}</span>
                  {p.completed > 0 ? <Badge tone="green">ordered {p.completed}×</Badge> : p.reachedPayment ? <Badge tone="amber">reached payment</Badge> : <Badge tone="slate">browsing</Badge>}
                  <span className="text-xs text-slate-500">{p.sessions} session{p.sessions === 1 ? "" : "s"} · last {fmtDateTime(p.lastSeenAt)}</span>
                </div>
                <Fields cols={2}>
                  <Field label="Furthest step">{p.furthestStep ? `${p.furthestStep} (#${p.furthestStepIndex + 1})` : "—"}</Field>
                  <Field label="Dropped at">{p.droppedAt ? <span className="text-amber-300">{p.droppedAt}</span> : p.completed ? "completed" : "—"}</Field>
                </Fields>
                {Object.keys(p.lastConfig).length > 0 && (
                  <dl className="mt-2 grid grid-cols-2 gap-x-3 gap-y-1 text-xs">
                    {Object.entries(p.lastConfig).map(([k, v]) => (
                      <div key={k} className="flex min-w-0 gap-1.5">
                        <dt className="shrink-0 text-slate-500">{k.replace(/_/g, " ")}</dt>
                        <dd className="min-w-0 truncate text-slate-200" title={v}>{v}</dd>
                      </div>
                    ))}
                  </dl>
                )}
                {p.lastErrors.length > 0 && (
                  <ul className="mt-2 space-y-0.5 text-xs text-rose-300">
                    {p.lastErrors.map((e, i) => <li key={i} className="truncate" title={e}>⚠ {e}</li>)}
                  </ul>
                )}
              </div>
            ))}
          </div>
        )}
      </Card>

      <Card title={`Payment records (${payments.length})`} sub={failedPayments ? `${failedPayments} failed or needed 3-D Secure` : "Every checkout, charge, failure, refund and dispute we have on record"}>
        {payments.length === 0 ? (
          <Empty>No payment records yet. Records start from this release; older card top-ups are in the Billing tab ledger.</Empty>
        ) : (
          <div className="overflow-x-auto">
            <table className="w-full min-w-[640px] text-xs">
              <thead className="text-left text-slate-500">
                <tr><th className="py-1 pr-3">When</th><th className="pr-3">Outcome</th><th className="pr-3">Amount</th><th className="pr-3">Method</th><th className="pr-3">Country</th><th>Detail</th></tr>
              </thead>
              <tbody>
                {payments.map((p) => {
                  const d = (p.data ?? {}) as { declineCode?: string; reason?: string };
                  return (
                    <tr key={p.id} className="border-t border-white/[0.05] align-top">
                      <td className="whitespace-nowrap py-1 pr-3 text-slate-400">{fmtDateTime(p.createdAt)}</td>
                      <td className="pr-3"><Badge tone={OUTCOME_TONE[p.outcome ?? ""] ?? "slate"}>{(p.outcome ?? p.type).replace(/_/g, " ")}</Badge></td>
                      <td className="whitespace-nowrap pr-3 font-mono">{money(p.amountCents, p.currency)}</td>
                      <td className="pr-3">{[p.provider, p.method].filter(Boolean).join(" / ") || "—"}</td>
                      <td className="pr-3">{p.country ?? "—"}</td>
                      <td className="text-slate-300">{p.label}{d.declineCode ? <span className="ml-1 font-mono text-rose-300">({d.declineCode})</span> : null}</td>
                    </tr>
                  );
                })}
              </tbody>
            </table>
          </div>
        )}
      </Card>

      <Card
        title="Activity timeline"
        sub="Newest first. Pages and wizard steps come from the visitor and funnel logs; everything else from the activity record and the audit log."
        action={
          <span className="flex flex-wrap gap-1 text-xs">
            {[7, 30, 90, 180].map((d) => (
              <Link key={d} href={href(category, d)} className={`rounded-md border px-2 py-0.5 ${d === windowDays ? "border-brand-400/60 text-brand-200" : "border-white/10 text-slate-400 hover:text-slate-200"}`}>{d}d</Link>
            ))}
          </span>
        }
      >
        <nav className="mb-3 flex flex-wrap gap-1.5 text-xs" aria-label="Filter activity">
          <Link href={href(null)} className={`rounded-full border px-2.5 py-1 ${!category ? "border-brand-400/60 bg-brand-500/10 text-brand-200" : "border-white/10 text-slate-400 hover:text-slate-200"}`}>All</Link>
          {ACTIVITY_CATEGORIES.map((c) => (
