import { test } from "node:test";
import assert from "node:assert/strict";

/**
 * lib/activity-events.ts + lib/activity-client-labels.ts + lib/activity-timeline.ts
 * pure logic (signup-fixes 2026-10-06). A fake Prisma client is installed on
 * globalThis BEFORE lib/db is imported (lib/db.ts reuses globalThis.prisma), so
 * no test here can reach a real database.
 */
type Row = Record<string, unknown>;
const rows: Row[] = [];
(globalThis as unknown as { prisma: unknown }).prisma = {
  activityEvent: {
    async create({ data }: { data: Row }) {
      if (data.dedupeKey && rows.some((r) => r.dedupeKey === data.dedupeKey)) {
        throw Object.assign(new Error("Unique constraint failed"), { code: "P2002" });
      }
      rows.push(data);
      return data;
    },
    async createMany({ data }: { data: Row[] }) {
      let n = 0;
      for (const d of data) if (!d.dedupeKey || !rows.some((r) => r.dedupeKey === d.dedupeKey)) { rows.push(d); n++; }
      return { count: n };
    },
    async deleteMany({ where }: { where: { createdAt: { lt: Date } } }) {
      const before = rows.length;
      for (let i = rows.length - 1; i >= 0; i--) if ((rows[i].createdAt as Date) < where.createdAt.lt) rows.splice(i, 1);
      return { count: before - rows.length };
    },
  },
};

const ev = await import("../lib/activity-events.ts");
const labels = await import("../lib/activity-client-labels.ts");
const tl = await import("../lib/activity-timeline.ts");

test("IPs are truncated before storage (/24 IPv4, 3 hextets IPv6), junk is dropped", () => {
  assert.equal(ev.truncateIp("203.0.113.77"), "203.0.113.0");
  assert.equal(ev.truncateIp("::ffff:198.51.100.9"), "198.51.100.0");
  assert.equal(ev.truncateIp("2001:db8:85a3:8d3:1319:8a2e:370:7348"), "2001:db8:85a3::");
  assert.equal(ev.truncateIp("999.1.1.1"), null);
  assert.equal(ev.truncateIp("not-an-ip"), null);
  assert.equal(ev.truncateIp(null), null);
});

test("sanitizer drops secrets and content, keeps structured choices", () => {
  const out = ev.sanitizeActivityData({
    field: "region", value: "sgp1", password: "hunter2", apiToken: "x", cardNumber: "4242", cvc: "123",
    content: "file body", body: "ticket text", message: "chat text", command: "rm -rf /",
    nested: { secretKey: "s", ok: 1, text: "free text" },
  })!;
  assert.deepEqual(Object.keys(out).sort(), ["field", "nested", "value"]);
  assert.deepEqual(out.nested, { ok: 1 });
});

test("sanitizer truncates long strings and caps size", () => {
  const out = ev.sanitizeActivityData({ error: "x".repeat(1000) })!;
  assert.ok(String(out.error).length <= 301);
  const big: Record<string, unknown> = {};
  for (let i = 0; i < 40; i++) big[`k${i}`] = "y".repeat(290);
  const slim = ev.sanitizeActivityData(big)!;
  assert.ok(JSON.stringify(slim).length < 12000);
  assert.ok(Object.keys(slim).length <= 31);
});

test("routes keep only the path (verify/reset tokens in query strings never stored)", () => {
  assert.equal(ev.cleanRoute("/verify-email?token=abc#x"), "/verify-email");
  assert.equal(ev.cleanRoute("https://nxeon.cloud/dashboard/deploy?plan=1"), "nxeon.cloud/dashboard/deploy");
  assert.equal(ev.cleanRoute(""), null);
});

test("client beacon may only send client-marked types — never payments or auth", () => {
  assert.equal(ev.isClientActivityType("wizard.field"), true);
  assert.equal(ev.isClientActivityType("error.shown"), true);
  assert.equal(ev.isClientActivityType("payment.succeeded"), false);
  assert.equal(ev.isClientActivityType("auth.login"), false);
  assert.equal(ev.isClientActivityType("made.up"), false);
});

test("buildActivityRow: category from the catalogue, currency lowercased, bad country dropped", () => {
  const r = ev.buildActivityRow({ type: "payment.failed", amountCents: 1299.6, currency: "USD", country: "india", ip: "10.1.2.3" });
  assert.equal(r.category, "payment");
  assert.equal(r.amountCents, 1300);
  assert.equal(r.currency, "usd");
  assert.equal(r.country, null);
  assert.equal(r.ipPrefix, "10.1.2.0");
  assert.equal(r.label, "Payment failed");
});

test("recordActivity is idempotent on dedupeKey and never throws", async () => {
  rows.length = 0;
  assert.equal(await ev.recordActivity({ type: "payment.succeeded", userId: "u1", dedupeKey: "stripe:evt_1" }), "created");
  assert.equal(await ev.recordActivity({ type: "payment.succeeded", userId: "u1", dedupeKey: "stripe:evt_1" }), "duplicate");
  assert.equal(rows.length, 1);
  assert.equal(await ev.recordActivity({ type: "nope" as never }), "error");
});

test("prune keeps rows inside the retention window", async () => {
  rows.length = 0;
  const now = new Date("2026-10-06T00:00:00Z");
  rows.push({ createdAt: new Date("2026-01-01T00:00:00Z") }, { createdAt: new Date("2026-09-30T00:00:00Z") });
  assert.equal(await ev.pruneActivity(180, now), 1);
  assert.equal(rows.length, 1);
  // a nonsense setting falls back to 180, never to "delete everything"
  rows.push({ createdAt: new Date("2026-10-05T00:00:00Z") });
  assert.equal(await ev.pruneActivity(0, now), 0);
});

test("client labels are built server-side from structured fields", () => {
  assert.equal(labels.clientEventLabel("wizard.field", { product: "game", field: "region", value: "sgp1", label: "Singapore" }), "Deploy wizard (game): region → Singapore");
  assert.equal(labels.clientEventLabel("wizard.field", { product: "vps", field: "addon", value: "backup", label: "Backups", on: false }), "Deploy wizard (vps): add-on removed → Backups");
  assert.match(labels.clientEventLabel("error.shown", { error: "Card declined", where: "deploy payment" }), /Saw an error on deploy payment: Card declined/);
});

test("audit actions map onto timeline categories", () => {
  assert.equal(tl.auditCategory("user.login"), "auth");
  assert.equal(tl.auditCategory("billing.card_declined"), "payment");
  assert.equal(tl.auditCategory("wallet.topup"), "payment");
  assert.equal(tl.auditCategory("gameserver.power"), "action");
});

test("wizard progress: furthest step, last config, drop point", () => {
  const t = (m: number) => new Date(Date.UTC(2026, 9, 6, 10, m));
  const funnel = [
    { product: "game", step: "Game", stepIndex: 1, type: "step", sessionId: "s1", createdAt: t(0), errorMessage: null, errorCode: null },
    { product: "game", step: "Server", stepIndex: 2, type: "step", sessionId: "s1", createdAt: t(1), errorMessage: null, errorCode: null },
    { product: "game", step: "Region", stepIndex: 3, type: "step", sessionId: "s1", createdAt: t(2), errorMessage: null, errorCode: null },
    { product: "game", step: "Payment", stepIndex: 4, type: "step", sessionId: "s1", createdAt: t(3), errorMessage: null, errorCode: null },
    { product: "game", step: "Payment", stepIndex: 4, type: "error", sessionId: "s1", createdAt: t(4), errorMessage: "Card declined", errorCode: "ORDER_ERROR" },
    { product: "vps", step: "Configure", stepIndex: 1, type: "step", sessionId: "s2", createdAt: t(10), errorMessage: null, errorCode: null },
    { product: "vps", step: "Complete", stepIndex: 8, type: "complete", sessionId: "s2", createdAt: t(12), errorMessage: null, errorCode: null },
  ];
  const fields = [
    { createdAt: t(1), type: "wizard.field", data: { product: "game", field: "game", value: "valheim", label: "Valheim" } },
    { createdAt: t(2), type: "wizard.field", data: { product: "game", field: "region", value: "fsn1", label: "Falkenstein" } },
    { createdAt: t(2), type: "wizard.field", data: { product: "game", field: "addon", value: "ip", label: "Dedicated IPv4", on: true } },
    { createdAt: t(5), type: "wizard.abandon", data: { product: "game", step: "Payment" } },
  ];
  const out = tl.summariseWizard(funnel, fields);
  const game = out.find((p) => p.product === "game")!;
  assert.equal(game.furthestStep, "Payment");
  assert.equal(game.reachedPayment, true);
  assert.equal(game.completed, 0);
  assert.equal(game.droppedAt, "Payment");
  assert.deepEqual(game.lastConfig, { game: "Valheim", region: "Falkenstein", addons: "Dedicated IPv4" });
  assert.deepEqual(game.lastErrors, ["Card declined"]);
  const vps = out.find((p) => p.product === "vps")!;
  assert.equal(vps.completed, 1);
  assert.equal(vps.droppedAt, null);
});
