    async createMany({ data }: { data: Row[] }) {
      let n = 0;
      for (const d of data) if (!d.dedupeKey || !rows.some((r) => r.dedupeKey === d.dedupeKey)) { rows.push(d); n++; }
      return { count: n };
    },
    async deleteMany({ where }: { where: { createdAt: { lt: Date } } }) {
      const before = rows.length;
      for (let i = rows.length - 1; i >= 0; i--) if ((rows[i].createdAt as Date) < where.createdAt.lt) rows.splice(i, 1);
      return { count: before - rows.length };
    },
  },
};

