import { test, before } from "node:test";
import assert from "node:assert/strict";
import Stripe from "stripe";

/**
 * Payment records (lib/payment-events.ts) and the Stripe webhook route that
 * writes them (app/api/stripe/webhook/route.ts): event mapping, decline / 3-D
 * Secure classification, signature verification and idempotency on redelivery.
 *
 * A fake Prisma client is installed on globalThis before anything imports
 * lib/db (lib/db.ts reuses globalThis.prisma), and the events used against the
 * real route are ones that need no Stripe API call, so nothing here touches a
 * database or the network.
 */
type Row = Record<string, unknown>;
const activity: Row[] = [];
const notifications: Row[] = [];
(globalThis as unknown as { prisma: unknown }).prisma = {
  activityEvent: {
    async create({ data }: { data: Row }) {
      if (data.dedupeKey && activity.some((r) => r.dedupeKey === data.dedupeKey)) {
        throw Object.assign(new Error("Unique constraint failed on dedupeKey"), { code: "P2002" });
      }
      activity.push(data);
      return data;
    },
  },
  user: {
    async findFirst() { return null; },
    async findMany() { return [{ id: "admin1" }]; },
  },
  notification: { async createMany({ data }: { data: Row[] }) { notifications.push(...data); return { count: data.length }; } },
};

const SECRET = "whsec_test_signupfixes";
process.env.STRIPE_SECRET_KEY = process.env.STRIPE_SECRET_KEY || "sk_test_signupfixes_dummy";
process.env.STRIPE_WEBHOOK_SECRET = SECRET;

let pe: typeof import("../lib/payment-events.ts");
before(async () => {
  pe = await import("../lib/payment-events.ts");
});

function event(type: string, object: Record<string, unknown>, id = `evt_${Math.random().toString(36).slice(2)}`): Stripe.Event {
  return { id, type, created: 1_791_000_000, data: { object }, object: "event", api_version: "2026-06-24", livemode: false, pending_webhooks: 1, request: null } as unknown as Stripe.Event;
}

test("checkout.session.completed (paid) -> payment.succeeded with method, amount, country, purpose", () => {
  const m = pe.stripeEventToActivity(event("checkout.session.completed", {
    id: "cs_1", mode: "payment", payment_status: "paid", amount_total: 1278, currency: "usd", payment_method_types: ["card"],
    metadata: { nxeonUserId: "u1", nxeonGameOrder: "{}" }, customer_details: { address: { country: "SG" } }, customer: "cus_1", payment_intent: "pi_1",
  }))!;
  assert.equal(m.type, "payment.succeeded");
  assert.equal(m.outcome, "succeeded");
  assert.equal(m.userId, "u1");
  assert.equal(m.method, "card");
  assert.equal(m.amountCents, 1278);
  assert.equal(m.country, "SG");
  assert.equal((m.data as Row).purpose, "game_order");
});

test("a delayed local method (PayNow) completing unpaid is 'pending', not success", () => {
  const m = pe.stripeEventToActivity(event("checkout.session.completed", {
    id: "cs_2", mode: "payment", payment_status: "unpaid", amount_total: 1700, currency: "sgd", payment_method_types: ["paynow"],
    metadata: { nxeonUserId: "u1", nxeonLocalPay: "paynow", nxeonCreditUsdCents: "1278" },
  }))!;
  assert.equal(m.type, "payment.pending");
  assert.equal(m.method, "paynow");
  assert.equal(m.currency, "sgd");
