test("expired / async-failed sessions are recorded; card-setup sessions are not payments", () => {
  assert.equal(pe.stripeEventToActivity(event("checkout.session.expired", { id: "cs_3", mode: "payment", metadata: {} }))!.type, "payment.checkout_expired");
  assert.equal(pe.stripeEventToActivity(event("checkout.session.async_payment_failed", { id: "cs_4", mode: "payment", metadata: { nxeonLocalPay: "upi" } }))!.type, "payment.failed");
  assert.equal(pe.stripeEventToActivity(event("checkout.session.completed", { id: "cs_5", mode: "setup", metadata: {} })), null);
});

test("payment_intent.payment_failed keeps decline code, card country and the 3-D Secure flag", () => {
  const decline = pe.stripeEventToActivity(event("payment_intent.payment_failed", {
    id: "pi_9", amount: 899, currency: "usd", metadata: {},
    last_payment_error: { code: "card_declined", decline_code: "insufficient_funds", type: "card_error", payment_method: { type: "card", card: { country: "IN", brand: "visa", funding: "debit" } } },
  }))!;
  assert.equal(decline.type, "payment.failed");
  assert.equal(decline.country, "IN");
  assert.equal((decline.data as Row).declineCode, "insufficient_funds");
  assert.match(decline.label!, /insufficient funds/);
  const auth = pe.stripeEventToActivity(event("payment_intent.payment_failed", {
    id: "pi_10", amount: 899, currency: "usd", metadata: {},
    last_payment_error: { code: "payment_intent_authentication_failure", type: "invalid_request_error", payment_method: { type: "card", card: { country: "ID" } } },
  }))!;
  assert.equal(auth.type, "payment.requires_action");
  assert.equal((auth.data as Row).threeDS, true);
});

test("off-session success shares its key with the worker's own record (written once)", () => {
  const m = pe.stripeEventToActivity(event("payment_intent.succeeded", { id: "pi_r1", amount: 1278, currency: "usd", metadata: { nxeonUserId: "u1", nxeonChargeKey: "renew:srv:2026-10-01" } }))!;
  assert.equal(m.dedupeKey, "pi:pi_r1:succeeded");
  assert.equal(m.type, "payment.renewal");
  // an ordinary Checkout PaymentIntent's success is already the session event
  assert.equal(pe.stripeEventToActivity(event("payment_intent.succeeded", { id: "pi_c", amount: 1, currency: "usd", metadata: {} })), null);
});

test("refunds key on the refund id (admin action + webhook = one row); disputes are recorded", () => {
  const r = pe.stripeEventToActivity(event("charge.refunded", { id: "ch_1", amount_refunded: 500, currency: "usd", refunded: false, refunds: { data: [{ id: "re_1", amount: 500, reason: "requested_by_customer" }] }, metadata: {}, payment_method_details: { type: "card", card: { country: "BD" } } }))!;
  assert.equal(r.dedupeKey, "refund:re_1");
  assert.equal(r.country, "BD");
  const d = pe.stripeEventToActivity(event("charge.dispute.created", { id: "dp_1", amount: 1278, currency: "usd", reason: "fraudulent", status: "needs_response", charge: "ch_1", payment_intent: null }))!;
  assert.equal(d.type, "payment.dispute_opened");
  assert.equal(pe.stripeEventToActivity(event("customer.created", {})), null);
});

test("decline reasons read like a person wrote them", () => {
  assert.equal(pe.failureReason("card_declined", "do_not_honor"), "declined by the bank (do not honor)");
  assert.equal(pe.failureReason("expired_card", null), "card expired");
  assert.equal(pe.failureReason(null, null), "unknown reason");
  assert.equal(pe.purposeFromMetadata({ nxeonChargeKey: "autorecharge:u:2026-10-06:2000" }), "auto_recharge");
  assert.equal(pe.purposeFromMetadata({}), "topup");
});

test("webhook: bad signature is refused (400) and records nothing", async () => {
  const { POST } = await import("../app/api/stripe/webhook/route.ts");
  const { NextRequest } = await import("next/server");
  activity.length = 0;
  const payload = JSON.stringify(event("charge.dispute.created", { id: "dp_x", amount: 100, currency: "usd", reason: "general", status: "needs_response", charge: "ch_x", payment_intent: null }, "evt_bad"));
  const bad = Stripe.webhooks.generateTestHeaderString({ payload, secret: "whsec_wrong" });
  const res = await POST(new NextRequest("http://x/api/stripe/webhook", { method: "POST", body: payload, headers: { "stripe-signature": bad } }));
  assert.equal(res.status, 400);
  const none = await POST(new NextRequest("http://x/api/stripe/webhook", { method: "POST", body: payload }));
  assert.equal(none.status, 400);
  assert.equal(activity.length, 0);
});

test("webhook: a valid event is recorded once, a redelivery is ignored (idempotent)", async () => {
  const { POST } = await import("../app/api/stripe/webhook/route.ts");
  const { NextRequest } = await import("next/server");
  activity.length = 0;
  notifications.length = 0;
  const payload = JSON.stringify(event("charge.dispute.created", { id: "dp_ok", amount: 1278, currency: "usd", reason: "fraudulent", status: "needs_response", charge: "ch_ok", payment_intent: null, evidence_details: { due_by: 1_792_000_000 } }, "evt_dispute_1"));
  for (let i = 0; i < 2; i++) {
    const sig = Stripe.webhooks.generateTestHeaderString({ payload, secret: SECRET });
    const res = await POST(new NextRequest("http://x/api/stripe/webhook", { method: "POST", body: payload, headers: { "stripe-signature": sig } }));
    assert.equal(res.status, 200);
  }
  assert.equal(activity.length, 1);
  assert.equal(activity[0].dedupeKey, "stripe:evt_dispute_1");
  assert.equal(activity[0].type, "payment.dispute_opened");
  // the URGENT staff alert fires once, not once per redelivery
  assert.equal(notifications.length, 1);
  assert.match(String(notifications[0].title), /URGENT: card dispute/);
});
