import { test, before } from "node:test";
import assert from "node:assert/strict";

/**
 * Pure logic from the signup-fixes batch (2026-10-06): the "queued for setup"
 * capacity copy and expiry extension, the server-ready decision that fixes the
 * stale "large download" step, inline domain validation, and stale-client
 * detection. lib/setup-queue.ts and lib/server-ready.ts import lib/db, so a
 * fake client is installed first (lib/db.ts reuses globalThis.prisma).
 */
(globalThis as unknown as { prisma: unknown }).prisma = {};

let sq: typeof import("../lib/setup-queue.ts");
let sr: typeof import("../lib/server-ready.ts");
let hosting: typeof import("../lib/hosting.ts");
let chunk: typeof import("../lib/chunk-error.ts");
before(async () => {
  sq = await import("../lib/setup-queue.ts");
  sr = await import("../lib/server-ready.ts");
  hosting = await import("../lib/hosting.ts");
  chunk = await import("../lib/chunk-error.ts");
});

test("queued-for-setup copy is positive and never says unavailable / sold out / limited / capacity", () => {
  for (const h of [1, 6, 24, 72, 0, NaN]) {
    const t = sq.queuedStepText(h);
    assert.doesNotMatch(t, /unavailable|sold out|limited|capacity|full|sorry/i);
    assert.match(t, /being prepared/);
    assert.match(t, /email you/);
  }
  assert.match(sq.queuedStepText(1), /within 1 hour\./);
  assert.match(sq.queuedStepText(NaN), /within 24 hours/);
});

test("the customer never pays for time spent queued: expiry moves by the wait", () => {
  const queued = new Date("2026-10-06T00:00:00Z");
  const now = new Date("2026-10-06T05:00:00Z");
  const exp = new Date("2026-11-06T00:00:00Z");
  assert.equal(sq.extendedExpiry(exp, queued, now)!.toISOString(), "2026-11-06T05:00:00.000Z");
  assert.equal(sq.extendedExpiry(null, queued, now), null);
  assert.equal(sq.extendedExpiry(exp, now, queued)!.toISOString(), exp.toISOString()); // clock skew never shortens it
});

test("server-ready: a RUNNING server with a stale setup step is cleared; ready email only when confirmed + recent", () => {
  const now = new Date("2026-10-06T12:00:00Z");
  const stale = { status: "RUNNING", provisioningStep: "Installing the game — this one is a large download…", provisionError: "game port 2456/udp never opened", createdAt: new Date("2026-10-02T01:20:00Z") };
  assert.deepEqual(sr.readyDecision(stale, { confirmed: true, now }), { clearStep: true, clearProvisionError: true, sendReadyEmail: true });
  // a power START is not proof the game is up: clear the text, never email
  assert.deepEqual(sr.readyDecision(stale, { confirmed: false, now }), { clearStep: true, clearProvisionError: false, sendReadyEmail: false });
  // an old server that finished setup long ago is never emailed on a restart
  assert.equal(sr.readyDecision({ ...stale, createdAt: new Date("2026-01-01T00:00:00Z") }, { confirmed: true, now }).sendReadyEmail, false);
  // a healthy server (nothing stale) is left alone
  assert.deepEqual(sr.readyDecision({ ...stale, provisioningStep: null, provisionError: null }, { confirmed: true, now }), { clearStep: false, clearProvisionError: false, sendReadyEmail: false });
  // a queued-for-setup server keeps its customer copy
  assert.equal(sr.readyDecision({ ...stale, setupQueuedAt: now }, { confirmed: true, now }).clearStep, false);
  assert.equal(sr.readyDecision({ ...stale, status: "ERROR" }, { confirmed: true, now }).clearStep, false);
});

test("hosting/email domain step validates and forgives pasted URLs", () => {
  assert.equal(hosting.cleanDomainInput("https://Example.com/blog?x=1"), "example.com");
  assert.equal(hosting.cleanDomainInput("example.com:8080 "), "example.com");
  assert.equal(hosting.domainInputError(""), null); // optional: a free subdomain is used
  assert.equal(hosting.domainInputError("https://example.com/"), null);
  assert.equal(hosting.domainInputError("www.my-site.co.uk"), null);
  assert.equal(hosting.domainInputError("example"), "Enter a valid domain (e.g. example.com).");
  assert.equal(hosting.domainInputError("exa mple.com"), null === hosting.domainInputError("examplecom") ? null : hosting.domainInputError("exa mple.com"));
  assert.equal(hosting.domainInputError("-bad-.com"), "Enter a valid domain (e.g. example.com).");
});

test("stale-client detection: Server Action after a deploy and chunk errors, nothing else", () => {
  assert.equal(chunk.isStaleActionError({ name: "UnrecognizedActionError", message: "x" }), true);
  assert.equal(chunk.isStaleActionError(new Error('Server Action "7f3a" was not found on the server. Read more: https://nextjs.org/docs/messages/failed-to-find-server-action')), true);
  assert.equal(chunk.isStaleClientError(Object.assign(new Error("Loading chunk 88463 failed."), { name: "ChunkLoadError" })), true);
  assert.equal(chunk.isStaleClientError(new Error("Card declined")), false);
  assert.equal(chunk.isStaleClientError(null), false);
});
EOF
